const express = require('express');
const session = require('express-session');
const PgSession = require('connect-pg-simple')(session);
const helmet = require('helmet');
const multer = require('multer');
const bcrypt = require('bcryptjs');
const PDFDocument = require('pdfkit');
const { Pool } = require('pg');
const path = require('node:path');
const crypto = require('node:crypto');

const app = express();
const logoUpload = multer({ storage: multer.memoryStorage(), limits: { fileSize: 3 * 1024 * 1024, files: 1 } });
const photoUpload = multer({ storage: multer.memoryStorage(), limits: { fileSize: 2 * 1024 * 1024, files: 8 } });
const isProduction = process.env.NODE_ENV === 'production';
if (!process.env.DATABASE_URL) { console.error('DATABASE_URL non configurato.'); process.exit(1); }
if (!process.env.SESSION_SECRET || process.env.SESSION_SECRET.length < 32) { console.error('SESSION_SECRET deve essere configurato con almeno 32 caratteri.'); process.exit(1); }
const pool = new Pool({
  connectionString: process.env.DATABASE_URL,
  ssl: process.env.PGSSL === 'require' ? { rejectUnauthorized: false } : false,
  max: Number(process.env.DB_POOL_MAX || 10),
  idleTimeoutMillis: 30000,
  connectionTimeoutMillis: 10000
});

app.set('trust proxy', 1);
app.disable('x-powered-by');
app.use(helmet({ contentSecurityPolicy: { directives: {
  defaultSrc: ["'self'"], styleSrc: ["'self'"], scriptSrc: ["'self'"],
  imgSrc: ["'self'", 'data:'], formAction: ["'self'"], objectSrc: ["'none'"], upgradeInsecureRequests: isProduction ? [] : null
} }}));
app.use(express.urlencoded({ extended: false, limit: '1mb' }));
app.use(express.static(path.resolve(__dirname, '../public')));
app.use('/assets', express.static(path.resolve(__dirname, '../assets'), { maxAge: isProduction ? '1d' : 0 }));
app.use(session({
  store: new PgSession({ pool, tableName: 'user_sessions', createTableIfMissing: true }),
  name: 'go.sid', secret: process.env.SESSION_SECRET,
  resave: false, saveUninitialized: false,
  cookie: { httpOnly: true, secure: isProduction, sameSite: 'lax', maxAge: 1000 * 60 * 60 * 10 }
}));
app.get('/workshop-logo',needAuth,async(req,res,next)=>{try{const r=await pool.query('SELECT logo_data,logo_mime FROM workshop_settings WHERE id=1');if(!r.rows[0]?.logo_data)return res.sendFile(path.resolve(__dirname,'../assets/brand/go-logo.png'));res.setHeader('Cache-Control','private, max-age=300');res.type(r.rows[0].logo_mime).send(r.rows[0].logo_data);}catch(e){next(e);}});
app.use('/settings/logo',needAuth,allow('owner','admin'),logoUpload.single('logo'));
app.use('/work-orders/:id/photos',needAuth,allow('owner','admin','manager','reception','mechanic'),photoUpload.array('photos',8));
app.use((req,res,next)=>{if(req.session.user?.role==='accountant'){if(req.path==='/')return res.redirect('/invoices');if(!req.path.startsWith('/invoices')&&req.path!=='/logout')return res.status(403).send(page('Accesso limitato','<section class="card"><p>Questo account può consultare solo i documenti contabili autorizzati.</p><a class="button" href="/invoices">Vai a fatture e pagamenti</a></section>',req.session.user,'invoices'));}next();});

const esc = value => String(value ?? '').replace(/[&<>"']/g, ch => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[ch]));
const fmtDate = value => value ? new Intl.DateTimeFormat('it-IT', { dateStyle: 'short', timeZone: 'Europe/Rome' }).format(new Date(value)) : '—';
const money = value => new Intl.NumberFormat('it-IT', { style: 'currency', currency: 'EUR' }).format(Number(value || 0));
const navIcons = {dashboard:'dashboard',bookings:'calendario',customers:'clienti',vehicles:'veicoli',orders:'lavori',inventory:'ricambi',invoices:'fatture',team:'utenti',settings:'impostazioni'};
const statuses = {
  checked_in: 'Presa in carico', diagnosis: 'Diagnosi', quote_pending: 'Preventivo da approvare', waiting_parts: 'In attesa ricambi',
  scheduled: 'Programmato', in_progress: 'In lavorazione', quality_check: 'Controllo qualità', testing: 'Test', ready: 'Pronta',
  invoiced: 'Fatturata', delivered: 'Consegnata', closed: 'Chiusa', cancelled: 'Annullata'
};
function csrf(req) { if (!req.session.csrf) req.session.csrf = crypto.randomBytes(24).toString('hex'); return req.session.csrf; }
app.use((req, res, next) => {
  if (req.method === 'POST' && req.path !== '/healthz') {
    const token = req.body?._csrf;
    if (!token || token !== req.session.csrf) return res.status(403).send(page('Richiesta non valida', '<section class="card"><h1>Richiesta non valida</h1><p>Ricarica la pagina e riprova.</p></section>', req.session.user));
  }
  next();
});
function page(title, body, user, active = '') {
  const allNavItems=[['/', 'Panoramica', 'dashboard'], ['/bookings', 'Prenotazioni', 'bookings'], ['/customers', 'Clienti', 'customers'], ['/vehicles', 'Veicoli', 'vehicles'], ['/work-orders', 'Ordini di lavoro', 'orders'], ['/inventory', 'Magazzino', 'inventory'], ['/invoices','Fatture e pagamenti','invoices'], ['/team', 'Utenti e meccanici', 'team'], ['/settings', 'Impostazioni officina', 'settings']];
  const navItems=user?.role==='accountant'?[['/invoices','Fatture e pagamenti','invoices']]:allNavItems;
  const nav = user ? `<aside class="sidebar"><a class="brand" href="/"><img src="/assets/brand/go-logo.png" alt="GO Gestione Officina"></a><nav>
    ${navItems.map(([href,label,key]) => `<a class="nav-link ${active===key?'active':''}" href="${href}"><img src="/assets/icons/${navIcons[key]}.png" alt="" aria-hidden="true">${label}</a>`).join('')}
    </nav><div class="sidebar-foot"><span>${esc(user.name)}</span><form method="post" action="/logout"><input type="hidden" name="_csrf" value="${esc(user.csrfToken||'')}"><button class="link-button">Esci</button></form></div></aside>` : '';
  const token = user ? user.csrfToken || '' : '';
  const content = `<div class="shell ${user?'':'shell-login'}">${nav}<main class="main"><header class="topbar"><div><span class="eyebrow">GO · GESTIONE OFFICINA</span><h1>${esc(title)}</h1></div>${user?`<div class="top-actions"><form class="global-search" method="get" action="/search"><input type="search" name="q" placeholder="Targa, VIN, cliente, telefono, ordine" aria-label="Ricerca globale"><button class="button">Cerca</button></form><div class="user-chip">${esc(user.name)}<span>${esc(user.role)}</span></div></div>`:''}</header>${body}</main></div>`;
  // Forms retrieve their CSRF token from the page-level meta tag.
  return `<!doctype html><html lang="it"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="csrf-token" content="${esc(token)}"><title>${esc(title)} · GO Gestione Officina</title><link rel="stylesheet" href="/app.css"><script defer src="/app.js"></script></head><body>${content}</body></html>`;
}
function formToken(req) { return `<input type="hidden" name="_csrf" value="${esc(csrf(req))}">`; }
function needAuth(req, res, next) { if (!req.session.user) return res.redirect('/login'); next(); }
function allow(...roles) { return (req,res,next) => roles.includes(req.session.user?.role) ? next() : res.status(403).send(page('Accesso negato','<section class="card"><p>Non hai i permessi per questa funzione.</p></section>',req.session.user)); }
function flash(req, value) { req.session.flash = value; }
function takeFlash(req) { const value=req.session.flash; delete req.session.flash; return value ? `<div class="notice">${esc(value)}</div>` : ''; }
function input(label,name,type='text',value='',required=false) { return `<label>${esc(label)}<input name="${name}" type="${type}" value="${esc(value)}" ${required?'required':''}></label>`; }
function select(label,name,options,value='') { return `<label>${esc(label)}<select name="${name}">${options.map(([v,l])=>`<option value="${esc(v)}" ${v===value?'selected':''}>${esc(l)}</option>`).join('')}</select></label>`; }
function drawWorkshopLogo(pdf, logoData) { try { pdf.image(logoData ? Buffer.from(logoData) : path.resolve(__dirname,'../assets/brand/go-logo.png'),48,42,{fit:[135,60]}); } catch(error) { console.error('Logo PDF non disponibile:',error.message); } }

app.get('/healthz', async (_req,res) => { try { await pool.query('SELECT 1'); res.status(200).json({status:'ok'}); } catch { res.status(503).json({status:'database unavailable'}); } });
app.get('/search',needAuth,async(req,res,next)=>{try{const term=String(req.query.q||'').trim().slice(0,80);if(!term)return res.redirect('/');const pattern=`%${term}%`;const [customers,vehicles,orders]=await Promise.all([pool.query(`SELECT id,name,phone FROM customers WHERE name ILIKE $1 OR phone ILIKE $1 ORDER BY name LIMIT 12`,[pattern]),pool.query(`SELECT v.id,v.plate,v.make,v.model,c.name AS customer FROM vehicles v JOIN customers c ON c.id=v.customer_id WHERE v.plate ILIKE $1 OR v.vin ILIKE $1 OR v.make ILIKE $1 OR v.model ILIKE $1 ORDER BY v.plate LIMIT 12`,[pattern]),pool.query(`SELECT w.id,w.status,v.plate,c.name AS customer FROM work_orders w JOIN vehicles v ON v.id=w.vehicle_id JOIN customers c ON c.id=w.customer_id WHERE w.id::text ILIKE $1 OR concat('GO-',w.id) ILIKE $1 ORDER BY w.created_at DESC LIMIT 12`,[pattern])]);const list=(rows,render,cols)=>rows.map(render).join('')||`<tr><td colspan="${cols}" class="empty">Nessun risultato</td></tr>`;const body=`<p class="muted">Risultati per: <strong>${esc(term)}</strong></p><section class="card"><h2>Clienti</h2><div class="table-wrap"><table><thead><tr><th>Cliente</th><th>Telefono</th></tr></thead><tbody>${list(customers.rows,c=>`<tr><td><a href="/customers/${c.id}">${esc(c.name)}</a></td><td>${esc(c.phone||'—')}</td></tr>`,2)}</tbody></table></div></section><section class="card"><h2>Veicoli</h2><div class="table-wrap"><table><thead><tr><th>Targa</th><th>Veicolo</th><th>Cliente</th></tr></thead><tbody>${list(vehicles.rows,v=>`<tr><td><a href="/vehicles/${v.id}">${esc(v.plate)}</a></td><td>${esc(v.make)} ${esc(v.model)}</td><td>${esc(v.customer)}</td></tr>`,3)}</tbody></table></div></section><section class="card"><h2>Ordini di lavoro</h2><div class="table-wrap"><table><thead><tr><th>Ordine</th><th>Targa</th><th>Cliente</th><th>Stato</th></tr></thead><tbody>${list(orders.rows,w=>`<tr><td><a href="/work-orders/${w.id}">GO-${w.id}</a></td><td>${esc(w.plate)}</td><td>${esc(w.customer)}</td><td>${esc(statuses[w.status]||w.status)}</td></tr>`,4)}</tbody></table></div></section>`;res.send(page('Ricerca',body,req.session.user));}catch(e){next(e);}});
app.get('/login', (req,res) => req.session.user ? res.redirect('/') : res.send(page('Accedi', `${takeFlash(req)}<section class="login-card card"><img src="/assets/brand/go-logo.png" alt="GO Gestione Officina"><h2>Accedi al gestionale</h2><form method="post" action="/login">${formToken(req)}${input('Email','email','email','',true)}${input('Password','password','password','',true)}<button class="button primary">Accedi</button></form><p class="muted">L’accesso iniziale va creato dall’amministratore del sistema.</p></section>`)));
app.post('/login', async (req,res,next) => { try { const result=await pool.query('SELECT id,name,email,password_hash,role FROM users WHERE lower(email)=lower($1) AND active=true',[req.body.email||'']); const u=result.rows[0]; if (!u || !await bcrypt.compare(req.body.password||'',u.password_hash)) { flash(req,'Email o password non corretti.'); return res.redirect('/login'); } req.session.regenerate(err=>{ if(err)return next(err); const token=crypto.randomBytes(24).toString('hex'); req.session.csrf=token; req.session.user={id:u.id,name:u.name,email:u.email,role:u.role,csrfToken:token}; res.redirect('/'); }); } catch(e){next(e);} });
app.post('/logout', needAuth, (req,res)=>req.session.destroy(()=>res.redirect('/login')));

app.get('/', needAuth, async (req,res,next)=>{ try {
  const [orders, bookings, timers, stock] = await Promise.all([
    pool.query(`SELECT w.id,w.status,w.target_date,v.plate,v.make,v.model,c.name AS customer FROM work_orders w JOIN vehicles v ON v.id=w.vehicle_id JOIN customers c ON c.id=w.customer_id WHERE w.status NOT IN ('closed','cancelled') ORDER BY w.created_at DESC LIMIT 8`),
    pool.query(`SELECT b.id,b.starts_at,b.reason,v.plate,c.name AS customer FROM bookings b JOIN vehicles v ON v.id=b.vehicle_id JOIN customers c ON c.id=b.customer_id WHERE b.starts_at >= now()-interval '1 day' AND b.status NOT IN ('cancelled','completed') ORDER BY b.starts_at LIMIT 6`),
    pool.query(`SELECT t.id,t.started_at,t.paused_at,t.pause_seconds,u.name AS mechanic,o.title,w.id AS order_id,v.plate FROM time_entries t JOIN users u ON u.id=t.user_id JOIN work_operations o ON o.id=t.operation_id JOIN work_orders w ON w.id=o.work_order_id JOIN vehicles v ON v.id=w.vehicle_id WHERE t.stopped_at IS NULL ORDER BY t.started_at`),
    pool.query(`SELECT count(*)::int AS count FROM inventory_items WHERE quantity<=minimum_quantity`)
  ]);
  const orderRows=orders.rows.map(x=>`<tr><td><a href="/work-orders/${x.id}">GO-${x.id}</a></td><td>${esc(x.plate)} · ${esc(x.make)} ${esc(x.model)}</td><td>${esc(x.customer)}</td><td><span class="badge">${esc(statuses[x.status]||x.status)}</span></td><td>${fmtDate(x.target_date)}</td></tr>`).join('')||'<tr><td colspan="5" class="empty">Nessun ordine aperto</td></tr>';
  const bookingRows=bookings.rows.map(x=>`<tr><td>${new Intl.DateTimeFormat('it-IT',{dateStyle:'short',timeStyle:'short',timeZone:'Europe/Rome'}).format(new Date(x.starts_at))}</td><td>${esc(x.plate)}</td><td>${esc(x.customer)}</td><td>${esc(x.reason)}</td></tr>`).join('')||'<tr><td colspan="4" class="empty">Nessun appuntamento imminente</td></tr>';
  const timerCards=timers.rows.map(x=>`<div class="timer-row"><div><strong>${esc(x.mechanic)} ${x.paused_at?'<span class="badge warning">In pausa</span>':'<span class="badge good">Attivo</span>'}</strong><span>${esc(x.plate)} · ${esc(x.title)}</span></div><span class="live-timer" data-start="${new Date(x.started_at).getTime()}" data-paused="${x.paused_at?new Date(x.paused_at).getTime():''}" data-pause-seconds="${Number(x.pause_seconds)}">00:00:00</span></div>`).join('')||'<p class="empty">Nessun timer attivo o in pausa</p>';
  const body=`${takeFlash(req)}<section class="stats"><article class="stat card"><span>Ordini aperti</span><strong>${orders.rowCount}</strong></article><article class="stat card"><span>Appuntamenti</span><strong>${bookings.rowCount}</strong></article><article class="stat card"><span>Timer attivi</span><strong>${timers.rowCount}</strong></article><article class="stat card"><span>Articoli da riordinare</span><strong>${stock.rows[0].count}</strong></article></section><div class="grid-two"><section class="card"><div class="section-heading"><h2>Vetture in officina</h2><a class="button small" href="/work-orders/new">Nuovo ordine</a></div><div class="table-wrap"><table><thead><tr><th>Ordine</th><th>Veicolo</th><th>Cliente</th><th>Stato</th><th>Obiettivo</th></tr></thead><tbody>${orderRows}</tbody></table></div></section><section class="card"><div class="section-heading"><h2>Timer in corso</h2></div>${timerCards}<h2 class="subhead">Prossimi appuntamenti</h2><div class="table-wrap"><table><thead><tr><th>Quando</th><th>Targa</th><th>Cliente</th><th>Motivo</th></tr></thead><tbody>${bookingRows}</tbody></table></div></section></div>`;
  res.send(page('Panoramica',body,req.session.user,'dashboard'));
} catch(e){next(e);} });

app.get('/customers', needAuth, async (req,res,next)=>{ try { const q=(req.query.q||'').trim(); const r=await pool.query(`SELECT * FROM customers WHERE ($1='' OR name ILIKE '%'||$1||'%' OR phone ILIKE '%'||$1||'%' OR email ILIKE '%'||$1||'%') ORDER BY name LIMIT 200`,[q]); const rows=r.rows.map(c=>`<tr><td><a href="/customers/${c.id}">${esc(c.name)}</a></td><td>${esc(c.phone)}</td><td>${esc(c.email)}</td><td>${esc(c.vat_number||c.tax_code)}</td></tr>`).join('')||'<tr><td colspan="4" class="empty">Nessun cliente registrato</td></tr>'; res.send(page('Clienti',`${takeFlash(req)}<section class="card"><div class="section-heading"><form class="inline-form"><input name="q" placeholder="Cerca cliente, telefono o email" value="${esc(q)}"><button class="button">Cerca</button></form><a class="button primary" href="/customers/new">Nuovo cliente</a></div><div class="table-wrap"><table><thead><tr><th>Cliente</th><th>Telefono</th><th>Email</th><th>CF / P. IVA</th></tr></thead><tbody>${rows}</tbody></table></div></section>`,req.session.user,'customers')); }catch(e){next(e);} });
app.get('/customers/new',needAuth,(req,res)=>res.send(page('Nuovo cliente',`<section class="card"><form method="post" action="/customers">${formToken(req)}<div class="form-grid">${select('Tipo','kind',[['person','Persona'],['business','Azienda']])}${input('Nome o ragione sociale','name','text','',true)}${input('Codice fiscale','tax_code')}${input('Partita IVA','vat_number')}${input('Email','email','email')}${input('Telefono','phone','tel')}${input('Indirizzo','address')}</div><label>Note<textarea name="notes"></textarea></label><button class="button primary">Salva cliente</button></form></section>`,req.session.user,'customers')));
app.post('/customers',needAuth,async(req,res,next)=>{try{const r=await pool.query(`INSERT INTO customers(kind,name,tax_code,vat_number,email,phone,address,notes) VALUES($1,$2,$3,$4,$5,$6,$7,$8) RETURNING id`,[req.body.kind,req.body.name,req.body.tax_code||'',req.body.vat_number||'',req.body.email||'',req.body.phone||'',req.body.address||'',req.body.notes||'']); await pool.query('INSERT INTO audit_log(user_id,action,entity_type,entity_id) VALUES($1,$2,$3,$4)',[req.session.user.id,'create','customer',String(r.rows[0].id)]); flash(req,'Cliente creato.');res.redirect(`/customers/${r.rows[0].id}`);}catch(e){next(e);}});
app.get('/customers/:id',needAuth,async(req,res,next)=>{try{const c=(await pool.query('SELECT * FROM customers WHERE id=$1',[req.params.id])).rows[0];if(!c)return res.sendStatus(404);const vs=await pool.query('SELECT * FROM vehicles WHERE customer_id=$1 ORDER BY plate',[c.id]);const rows=vs.rows.map(v=>`<tr><td><a href="/vehicles/${v.id}">${esc(v.plate)}</a></td><td>${esc(v.make)} ${esc(v.model)}</td><td>${v.mileage.toLocaleString('it-IT')} km</td></tr>`).join('')||'<tr><td colspan="3" class="empty">Nessun veicolo associato</td></tr>';res.send(page(c.name,`${takeFlash(req)}<section class="card"><div class="detail-grid"><div><span class="muted">Telefono</span><strong>${esc(c.phone||'—')}</strong></div><div><span class="muted">Email</span><strong>${esc(c.email||'—')}</strong></div><div><span class="muted">Indirizzo</span><strong>${esc(c.address||'—')}</strong></div></div><div class="section-heading"><h2>Veicoli</h2><a class="button primary" href="/vehicles/new?customer_id=${c.id}">Aggiungi veicolo</a></div><div class="table-wrap"><table><thead><tr><th>Targa</th><th>Veicolo</th><th>Chilometraggio</th></tr></thead><tbody>${rows}</tbody></table></div></section>`,req.session.user,'customers'));}catch(e){next(e);}});

app.get('/vehicles',needAuth,async(req,res,next)=>{try{const r=await pool.query(`SELECT v.*,c.name AS customer FROM vehicles v JOIN customers c ON c.id=v.customer_id ORDER BY v.created_at DESC LIMIT 300`);const rows=r.rows.map(v=>`<tr><td><a href="/vehicles/${v.id}">${esc(v.plate)}</a></td><td>${esc(v.make)} ${esc(v.model)}</td><td>${esc(v.customer)}</td><td>${v.mileage.toLocaleString('it-IT')} km</td></tr>`).join('')||'<tr><td colspan="4" class="empty">Nessun veicolo registrato</td></tr>';res.send(page('Veicoli',`${takeFlash(req)}<section class="card"><div class="section-heading"><p class="muted">Archivio vetture e storico officina</p><a class="button primary" href="/vehicles/new">Nuovo veicolo</a></div><div class="table-wrap"><table><thead><tr><th>Targa</th><th>Veicolo</th><th>Cliente</th><th>Km</th></tr></thead><tbody>${rows}</tbody></table></div></section>`,req.session.user,'vehicles'));}catch(e){next(e);}});
app.get('/vehicles/new',needAuth,async(req,res,next)=>{try{const cs=await pool.query('SELECT id,name FROM customers ORDER BY name');const opts=cs.rows.map(c=>[String(c.id),c.name]);if(!opts.length)return res.redirect('/customers/new');res.send(page('Nuovo veicolo',`<section class="card"><form method="post" action="/vehicles">${formToken(req)}<div class="form-grid">${select('Cliente','customer_id',opts,req.query.customer_id||'')}${input('Targa','plate','text','',true)}${input('VIN','vin')}${input('Marca','make')}${input('Modello','model')}${input('Anno','year','number')}${input('Alimentazione','fuel')}${input('Chilometraggio','mileage','number','0')}</div><label>Note<textarea name="notes"></textarea></label><button class="button primary">Salva veicolo</button></form></section>`,req.session.user,'vehicles'));}catch(e){next(e);}});
app.post('/vehicles',needAuth,async(req,res,next)=>{try{const r=await pool.query(`INSERT INTO vehicles(customer_id,plate,vin,make,model,year,fuel,mileage,notes) VALUES($1,$2,$3,$4,$5,$6,$7,$8,$9) RETURNING id`,[req.body.customer_id,req.body.plate.toUpperCase(),req.body.vin||'',req.body.make||'',req.body.model||'',req.body.year||null,req.body.fuel||'',req.body.mileage||0,req.body.notes||'']);flash(req,'Veicolo registrato.');res.redirect(`/vehicles/${r.rows[0].id}`);}catch(e){next(e);}});
app.get('/vehicles/:id',needAuth,async(req,res,next)=>{try{const v=(await pool.query('SELECT v.*,c.name AS customer FROM vehicles v JOIN customers c ON c.id=v.customer_id WHERE v.id=$1',[req.params.id])).rows[0];if(!v)return res.sendStatus(404);const wo=await pool.query('SELECT id,status,created_at,complaint FROM work_orders WHERE vehicle_id=$1 ORDER BY created_at DESC',[v.id]);const rows=wo.rows.map(w=>`<tr><td><a href="/work-orders/${w.id}">GO-${w.id}</a></td><td>${fmtDate(w.created_at)}</td><td>${esc(statuses[w.status]||w.status)}</td><td>${esc(w.complaint)}</td></tr>`).join('')||'<tr><td colspan="4" class="empty">Nessun intervento registrato</td></tr>';res.send(page(`${v.plate} · ${v.make} ${v.model}`,`${takeFlash(req)}<section class="card"><div class="detail-grid"><div><span class="muted">Cliente</span><strong><a href="/customers/${v.customer_id}">${esc(v.customer)}</a></strong></div><div><span class="muted">VIN</span><strong>${esc(v.vin||'—')}</strong></div><div><span class="muted">Chilometraggio</span><strong>${v.mileage.toLocaleString('it-IT')} km</strong></div><div><span class="muted">Alimentazione</span><strong>${esc(v.fuel||'—')}</strong></div></div><div class="section-heading"><h2>Ordini di lavoro</h2><a class="button primary" href="/work-orders/new?vehicle_id=${v.id}">Apri ordine</a></div><div class="table-wrap"><table><thead><tr><th>Ordine</th><th>Data</th><th>Stato</th><th>Problema</th></tr></thead><tbody>${rows}</tbody></table></div></section>`,req.session.user,'vehicles'));}catch(e){next(e);}});

app.get('/bookings',needAuth,async(req,res,next)=>{try{const r=await pool.query(`SELECT b.*,v.plate,v.make,v.model,c.name AS customer FROM bookings b JOIN vehicles v ON v.id=b.vehicle_id JOIN customers c ON c.id=b.customer_id ORDER BY b.starts_at DESC LIMIT 300`);const rows=r.rows.map(b=>`<tr><td>${new Intl.DateTimeFormat('it-IT',{dateStyle:'short',timeStyle:'short',timeZone:'Europe/Rome'}).format(new Date(b.starts_at))}</td><td>${esc(b.plate)} · ${esc(b.make)} ${esc(b.model)}</td><td>${esc(b.customer)}</td><td>${esc(b.reason)}</td><td><span class="badge">${esc(b.status)}</span></td><td><form method="post" action="/bookings/${b.id}/check-in">${formToken(req)}<button class="button small">Presa in carico</button></form></td></tr>`).join('')||'<tr><td colspan="6" class="empty">Nessun appuntamento</td></tr>';res.send(page('Prenotazioni',`${takeFlash(req)}<section class="card"><div class="section-heading"><p class="muted">Appuntamenti e accettazioni</p><a class="button primary" href="/bookings/new">Nuovo appuntamento</a></div><div class="table-wrap"><table><thead><tr><th>Quando</th><th>Veicolo</th><th>Cliente</th><th>Motivo</th><th>Stato</th><th>Azione</th></tr></thead><tbody>${rows}</tbody></table></div></section>`,req.session.user,'bookings'));}catch(e){next(e);}});
app.get('/bookings/new',needAuth,async(req,res,next)=>{try{const r=await pool.query('SELECT v.id,v.plate,v.make,v.model,c.id AS customer_id,c.name FROM vehicles v JOIN customers c ON c.id=v.customer_id ORDER BY c.name,v.plate');const opts=r.rows.map(v=>[String(v.id),`${v.name} · ${v.plate} ${v.make} ${v.model}`]);res.send(page('Nuovo appuntamento',`<section class="card"><form method="post" action="/bookings">${formToken(req)}<div class="form-grid">${select('Veicolo e cliente','vehicle_id',opts)}${input('Data e ora','starts_at','datetime-local','',true)}${input('Motivo visita','reason','text','',true)}</div><label>Note<textarea name="notes"></textarea></label><button class="button primary">Conferma appuntamento</button></form></section>`,req.session.user,'bookings'));}catch(e){next(e);}});
app.post('/bookings',needAuth,async(req,res,next)=>{try{const v=await pool.query('SELECT customer_id FROM vehicles WHERE id=$1',[req.body.vehicle_id]);if(!v.rowCount)return res.status(400).send('Veicolo non valido');const r=await pool.query(`INSERT INTO bookings(customer_id,vehicle_id,starts_at,reason,notes,created_by) VALUES($1,$2,$3,$4,$5,$6) RETURNING id`,[v.rows[0].customer_id,req.body.vehicle_id,req.body.starts_at,req.body.reason,req.body.notes||'',req.session.user.id]);flash(req,'Appuntamento registrato.');res.redirect('/bookings');}catch(e){next(e);}});
app.post('/bookings/:id/check-in',needAuth,async(req,res,next)=>{const c=await pool.connect();try{await c.query('BEGIN');const b=await c.query('SELECT * FROM bookings WHERE id=$1 FOR UPDATE',[req.params.id]);if(!b.rowCount)throw new Error('Appuntamento non trovato');const r=await c.query(`INSERT INTO work_orders(customer_id,vehicle_id,booking_id,status,complaint,created_by) VALUES($1,$2,$3,'checked_in',$4,$5) RETURNING id`,[b.rows[0].customer_id,b.rows[0].vehicle_id,b.rows[0].id,b.rows[0].reason,req.session.user.id]);await c.query(`INSERT INTO work_operations(work_order_id,title,status) VALUES($1,'Diagnosi iniziale','pending')`,[r.rows[0].id]);await c.query(`UPDATE bookings SET status='completed' WHERE id=$1`,[b.rows[0].id]);await c.query('COMMIT');flash(req,`Presa in carico completata: ordine GO-${r.rows[0].id}.`);res.redirect(`/work-orders/${r.rows[0].id}`);}catch(e){await c.query('ROLLBACK');next(e);}finally{c.release();}});

app.get('/work-orders',needAuth,async(req,res,next)=>{try{const r=await pool.query(`SELECT w.*,v.plate,v.make,v.model,c.name AS customer FROM work_orders w JOIN vehicles v ON v.id=w.vehicle_id JOIN customers c ON c.id=w.customer_id ORDER BY w.created_at DESC LIMIT 300`);const rows=r.rows.map(w=>`<tr><td><a href="/work-orders/${w.id}">GO-${w.id}</a></td><td>${esc(w.plate)} · ${esc(w.make)} ${esc(w.model)}</td><td>${esc(w.customer)}</td><td><span class="badge">${esc(statuses[w.status]||w.status)}</span></td><td>${fmtDate(w.created_at)}</td></tr>`).join('')||'<tr><td colspan="5" class="empty">Nessun ordine</td></tr>';res.send(page('Ordini di lavoro',`${takeFlash(req)}<section class="card"><div class="section-heading"><p class="muted">Lavorazioni, tempi e avanzamento</p><a class="button primary" href="/work-orders/new">Nuovo ordine</a></div><div class="table-wrap"><table><thead><tr><th>Ordine</th><th>Veicolo</th><th>Cliente</th><th>Stato</th><th>Creato</th></tr></thead><tbody>${rows}</tbody></table></div></section>`,req.session.user,'orders'));}catch(e){next(e);}});
app.get('/work-orders/new',needAuth,async(req,res,next)=>{try{const r=await pool.query('SELECT v.id,v.plate,v.make,v.model,c.id AS customer_id,c.name FROM vehicles v JOIN customers c ON c.id=v.customer_id ORDER BY c.name,v.plate');const opts=r.rows.map(v=>[String(v.id),`${v.name} · ${v.plate} ${v.make} ${v.model}`]);res.send(page('Nuovo ordine di lavoro',`<section class="card"><form method="post" action="/work-orders">${formToken(req)}<div class="form-grid">${select('Veicolo e cliente','vehicle_id',opts,req.query.vehicle_id||'')}${input('Chilometraggio ingresso','mileage_in','number','0')}${input('Livello carburante / carica','fuel_level')}${input('Data obiettivo','target_date','date')}</div>${input('Problema segnalato','complaint','text','',true)}<label>Note accettazione<textarea name="notes"></textarea></label><button class="button primary">Crea ordine</button></form></section>`,req.session.user,'orders'));}catch(e){next(e);}});
app.post('/work-orders',needAuth,async(req,res,next)=>{const c=await pool.connect();try{await c.query('BEGIN');const v=await c.query('SELECT customer_id FROM vehicles WHERE id=$1',[req.body.vehicle_id]);if(!v.rowCount)throw new Error('Seleziona un veicolo valido');const r=await c.query(`INSERT INTO work_orders(customer_id,vehicle_id,status,complaint,mileage_in,fuel_level,target_date,notes,created_by) VALUES($1,$2,'checked_in',$3,$4,$5,$6,$7,$8) RETURNING id`,[v.rows[0].customer_id,req.body.vehicle_id,req.body.complaint,req.body.mileage_in||0,req.body.fuel_level||'',req.body.target_date||null,req.body.notes||'',req.session.user.id]);await c.query(`INSERT INTO work_operations(work_order_id,title) VALUES($1,'Diagnosi iniziale')`,[r.rows[0].id]);await c.query('INSERT INTO audit_log(user_id,action,entity_type,entity_id) VALUES($1,$2,$3,$4)',[req.session.user.id,'create','work_order',String(r.rows[0].id)]);await c.query('COMMIT');flash(req,'Ordine di lavoro creato.');res.redirect(`/work-orders/${r.rows[0].id}`);}catch(e){await c.query('ROLLBACK');next(e);}finally{c.release();}});
app.get('/work-orders/:id',needAuth,async(req,res,next)=>{
  try {
    const r=await pool.query(`SELECT w.*,v.plate,v.make,v.model,v.vin,c.name AS customer FROM work_orders w JOIN vehicles v ON v.id=w.vehicle_id JOIN customers c ON c.id=w.customer_id WHERE w.id=$1`,[req.params.id]);
    if(!r.rowCount)return res.sendStatus(404);
    const w=r.rows[0];
    const [ops,mechanics,estimate,checks,roadTests,photos,templates,acceptances,parts]=await Promise.all([
      pool.query(`SELECT o.*,coalesce(sum(CASE WHEN t.paused_at IS NOT NULL THEN extract(epoch from t.paused_at-t.started_at)-t.pause_seconds WHEN t.stopped_at IS NULL THEN extract(epoch from now()-t.started_at)-t.pause_seconds ELSE extract(epoch from t.stopped_at-t.started_at)-t.pause_seconds END),0)::int AS person_seconds,coalesce(extract(epoch from max(coalesce(t.stopped_at,t.paused_at,now()))-min(t.started_at)),0)::int AS elapsed_seconds FROM work_operations o LEFT JOIN time_entries t ON t.operation_id=o.id WHERE o.work_order_id=$1 GROUP BY o.id ORDER BY o.id`,[w.id]),
      pool.query(`SELECT id,name FROM users WHERE active=true AND role='mechanic' ORDER BY name`),
      pool.query(`SELECT * FROM estimates WHERE work_order_id=$1 ORDER BY version DESC LIMIT 1`,[w.id]),
      pool.query(`SELECT * FROM quality_checks WHERE work_order_id=$1 ORDER BY id`,[w.id]),
      pool.query(`SELECT * FROM road_tests WHERE work_order_id=$1 ORDER BY tested_at DESC LIMIT 5`,[w.id]),
      pool.query(`SELECT id,file_name,mime_type,created_at FROM documents WHERE work_order_id=$1 AND document_type='vehicle_photo' ORDER BY created_at DESC`,[w.id]),
      pool.query('SELECT repair_terms,privacy_notice FROM workshop_settings WHERE id=1'),
      pool.query('SELECT * FROM document_acceptances WHERE work_order_id=$1 ORDER BY accepted_at DESC',[w.id]),
      pool.query(`SELECT r.*,i.sku,i.description FROM inventory_reservations r JOIN inventory_items i ON i.id=r.item_id WHERE r.work_order_id=$1 ORDER BY r.created_at DESC`,[w.id])
    ]);
    const opRows=await Promise.all(ops.rows.map(async o=>{
      const [assignees,activeTimer]=await Promise.all([
        pool.query('SELECT user_id FROM operation_assignments WHERE operation_id=$1',[o.id]),
        pool.query('SELECT paused_at FROM time_entries WHERE operation_id=$1 AND user_id=$2 AND stopped_at IS NULL',[o.id,req.session.user.id])
      ]);
      const selected=assignees.rows.map(a=>String(a.user_id));
      const timerAction=!activeTimer.rowCount?`<form method="post" action="/operations/${o.id}/timer/start">${formToken(req)}<button class="button small primary">Avvia</button></form>`:activeTimer.rows[0].paused_at?`<form method="post" action="/operations/${o.id}/timer/resume">${formToken(req)}<button class="button small">Riprendi</button></form>`:`<form method="post" action="/operations/${o.id}/timer/pause">${formToken(req)}<input name="reason" placeholder="Motivo pausa" aria-label="Motivo pausa"><button class="button small">Pausa</button></form><form method="post" action="/operations/${o.id}/timer/stop">${formToken(req)}<button class="button small">Termina</button></form>`;
      return `<article class="operation"><div class="operation-head"><div><h3>${esc(o.title)}</h3><p class="muted">${esc(o.description||'Nessuna nota')}</p></div><span class="badge">${esc(o.status)}</span></div><div class="operation-actions"><span class="time-total">Tempo lavorato: ${Math.floor(o.person_seconds/3600)}h ${Math.floor((o.person_seconds%3600)/60)}m · intervallo calendario: ${Math.floor(o.elapsed_seconds/3600)}h ${Math.floor((o.elapsed_seconds%3600)/60)}m</span>${timerAction}</div><form class="assign-form" method="post" action="/operations/${o.id}/assign">${formToken(req)}<label>Meccanici assegnati<select name="user_ids" multiple size="${Math.min(3,Math.max(1,mechanics.rowCount))}">${mechanics.rows.map(m=>`<option value="${m.id}" ${selected.includes(String(m.id))?'selected':''}>${esc(m.name)}</option>`).join('')}</select></label><button class="button small">Salva assegnazioni</button></form></article>`;
    }));
    const e=estimate.rows[0];
    const estimateBox=e?`<p>Versione ${e.version} · Stato: <span class="badge">${esc(e.status)}</span> · ${e.valid_until?`Valido fino al ${fmtDate(e.valid_until)}`:'Senza scadenza impostata'}</p><a class="button" href="/estimates/${e.id}/pdf">Scarica preventivo PDF</a>${e.status==='draft'||e.status==='sent'?`<form class="inline-form" method="post" action="/estimates/${e.id}/decision">${formToken(req)}<button class="button primary" name="decision" value="approved">Registra approvazione</button><button class="button" name="decision" value="rejected">Registra rifiuto</button></form>`:''}`:'<p class="muted">Nessun preventivo ancora registrato.</p>';
    const eCurrent=estimate.rows[0];
    const latestTest=roadTests.rows[0];
    const qualityPassed=checks.rowCount>=6&&checks.rows.every(ch=>ch.passed===true)&&latestTest?.result==='passed';
    const readyAction=qualityPassed&&w.status!=='ready'&&w.status!=='delivered'&&w.status!=='closed'?`<form method="post" action="/work-orders/${w.id}/mark-ready">${formToken(req)}<button class="button primary">Conferma auto pronta</button></form>`:'';
    const createInvoice=eCurrent?.status==='approved'&&w.status==='ready'?`<form method="post" action="/work-orders/${w.id}/invoice">${formToken(req)}<button class="button primary">Prepara documento gestionale</button></form>`:'';
    const checkRows=checks.rows.map(ch=>`<tr><td>${esc(ch.label)}</td><td>${ch.passed===null?'<span class="badge warning">Da controllare</span>':ch.passed?'<span class="badge good">Superato</span>':'<span class="badge warning">Non superato</span>'}</td><td>${esc(ch.note||'—')}</td><td><form class="inline-form" method="post" action="/quality-checks/${ch.id}">${formToken(req)}<input type="hidden" name="work_order_id" value="${w.id}"><select name="passed" aria-label="Esito"><option value="true">Superato</option><option value="false">Non superato</option></select><input name="note" placeholder="Nota / anomalia"><button class="button small">Registra</button></form></td></tr>`).join('');
    const roadRows=roadTests.rows.map(t=>`<tr><td>${fmtDate(t.tested_at)}</td><td>${esc(t.result)}</td><td>${Number(t.mileage_start).toLocaleString('it-IT')} → ${t.mileage_end===null?'—':Number(t.mileage_end).toLocaleString('it-IT')} km</td><td>${esc(t.notes||'')}</td></tr>`).join('')||'<tr><td colspan="4" class="empty">Nessun test registrato</td></tr>';
    const photoRows=photos.rows.map(p=>`<a class="vehicle-photo" href="/work-orders/${w.id}/documents/${p.id}" target="_blank" rel="noopener"><img src="/work-orders/${w.id}/documents/${p.id}" alt="Foto veicolo ${esc(p.file_name)}"><span>${esc(p.file_name)}</span></a>`).join('')||'<p class="muted">Nessuna fotografia di presa in carico.</p>';
    const terms=templates.rows[0]||{repair_terms:'',privacy_notice:''};const termsVersion=crypto.createHash('sha256').update(terms.repair_terms).digest('hex');const privacyVersion=crypto.createHash('sha256').update(terms.privacy_notice).digest('hex');
    const acceptanceRows=acceptances.rows.map(a=>`<tr><td>${esc(a.document_type==='repair_terms'?'Condizioni di riparazione':'Informativa privacy')}</td><td>${esc(a.accepted_by)}</td><td>${fmtDate(a.accepted_at)}</td><td>${esc(a.document_version.slice(0,12))}…</td></tr>`).join('')||'<tr><td colspan="4" class="empty">Nessuna presa visione registrata.</td></tr>';
    const partRows=parts.rows.map(p=>`<tr><td>${esc(p.sku||'')}</td><td><a href="/inventory/${p.item_id}">${esc(p.description)}</a></td><td>${Number(p.quantity)}</td><td>${esc(p.status)}</td></tr>`).join('')||'<tr><td colspan="4" class="empty">Nessun ricambio riservato a questo ordine.</td></tr>';
    const statusOpts=Object.entries(statuses).filter(([k])=>!['ready','invoiced','delivered','closed'].includes(k)).map(([k,v])=>[k,v]);
    const body=`${takeFlash(req)}<section class="card"><div class="section-heading"><div><span class="eyebrow">ORDINE GO-${w.id}</span><h2>${esc(w.plate)} · ${esc(w.make)} ${esc(w.model)}</h2><p class="muted">Cliente: ${esc(w.customer)} · VIN: ${esc(w.vin||'—')}</p></div><a class="button" href="/work-orders/${w.id}/pdf">Stampa scheda PDF</a></div><div class="detail-grid"><div><span class="muted">Ingresso</span><strong>${fmtDate(w.created_at)}</strong></div><div><span class="muted">Km ingresso</span><strong>${Number(w.mileage_in).toLocaleString('it-IT')}</strong></div><div><span class="muted">Stato</span><strong>${esc(statuses[w.status]||w.status)}</strong></div><div><span class="muted">Problema segnalato</span><strong>${esc(w.complaint)}</strong></div></div><form class="inline-form status-form" method="post" action="/work-orders/${w.id}/status">${formToken(req)}${select('Aggiorna stato','status',statusOpts,w.status)}<button class="button">Aggiorna stato</button></form></section><section class="card"><h2>Condizioni e informativa cliente</h2><p class="muted">La conferma viene registrata dall’operatore con nome, ora, versione e copia del testo mostrato; non equivale a una firma elettronica qualificata.</p><form method="post" action="/work-orders/${w.id}/acceptance">${formToken(req)}${input('Nome della persona che conferma','accepted_by','text','',true)}<input type="hidden" name="terms_version" value="${termsVersion}"><input type="hidden" name="privacy_version" value="${privacyVersion}"><label class="accept-row"><input type="checkbox" name="accept_terms" value="yes" ${terms.repair_terms?'':'disabled'}> Conferma ricezione e accettazione delle condizioni di riparazione${terms.repair_terms?'':' (testo non configurato)'}</label><details><summary>Condizioni applicabili</summary><p>${esc(terms.repair_terms||'Nessun testo configurato.')}</p></details><label class="accept-row"><input type="checkbox" name="ack_privacy" value="yes" ${terms.privacy_notice?'':'disabled'}> Conferma di aver ricevuto l’informativa privacy${terms.privacy_notice?'':' (testo non configurato)'}</label><details><summary>Informativa privacy</summary><p>${esc(terms.privacy_notice||'Nessun testo configurato.')}</p></details><button class="button">Registra presa visione</button></form><div class="table-wrap"><table><thead><tr><th>Documento</th><th>Persona</th><th>Data</th><th>Versione</th></tr></thead><tbody>${acceptanceRows}</tbody></table></div></section><section class="card"><div class="section-heading"><h2>Foto e documenti di presa in carico</h2></div><form class="inline-form photo-upload" method="post" action="/work-orders/${w.id}/photos" enctype="multipart/form-data">${formToken(req)}<label>Carica foto PNG/JPEG (massimo 8 file da 2 MB)<input name="photos" type="file" accept="image/png,image/jpeg" multiple required></label><button class="button">Salva foto</button></form><div class="photo-grid">${photoRows}</div></section><section class="card"><h2>Ricambi associati</h2><div class="table-wrap"><table><thead><tr><th>Codice</th><th>Articolo</th><th>Quantità</th><th>Stato</th></tr></thead><tbody>${partRows}</tbody></table></div></section><section class="card"><div class="section-heading"><h2>Lavorazioni e timer</h2></div>${opRows.join('')||'<p class="empty">Nessuna operazione</p>'}<form class="add-operation" method="post" action="/work-orders/${w.id}/operations">${formToken(req)}${input('Nuova operazione','title','text','',true)}${input('Descrizione','description')}<button class="button">Aggiungi operazione</button></form></section><section class="card"><div class="section-heading"><h2>Preventivo</h2><a class="button" href="/work-orders/${w.id}/estimate/new">Crea preventivo</a></div>${estimateBox}${createInvoice}</section><section class="card"><div class="section-heading"><h2>Controllo qualità</h2><form method="post" action="/work-orders/${w.id}/quality-checks/setup">${formToken(req)}<button class="button small">Prepara checklist</button></form></div><p class="muted">Tutte le verifiche e un test su strada superato sono necessari per segnare l’auto come pronta.</p><div class="table-wrap"><table><thead><tr><th>Controllo</th><th>Esito</th><th>Nota</th><th>Aggiorna</th></tr></thead><tbody>${checkRows||'<tr><td colspan="4" class="empty">Checklist non ancora preparata</td></tr>'}</tbody></table></div><form class="inline-form" method="post" action="/work-orders/${w.id}/road-tests">${formToken(req)}<input type="hidden" name="mileage_start" value="${Number(w.mileage_in)}">${input('Km dopo il test','mileage_end','number',String(Number(w.mileage_in)),true)}${select('Esito test','result',[['passed','Superato'],['failed','Non superato']])}${input('Esito e anomalie','notes')}<button class="button">Registra test</button></form><div class="table-wrap"><table><thead><tr><th>Data</th><th>Esito</th><th>Km</th><th>Note</th></tr></thead><tbody>${roadRows}</tbody></table></div>${readyAction}</section>`;
    res.send(page(`Ordine GO-${w.id}`,body,req.session.user,'orders'));
  } catch(e){next(e);}
});
app.post('/work-orders/:id/status',needAuth,async(req,res,next)=>{try{const target=req.body.status;if(!statuses[target]||['ready','invoiced','delivered','closed'].includes(target))throw new Error('Questo stato si raggiunge completando i controlli, il documento o la consegna dedicati.');const w=await pool.query('SELECT status FROM work_orders WHERE id=$1',[req.params.id]);if(!w.rowCount)return res.sendStatus(404);if(['scheduled','in_progress','quality_check','testing'].includes(target)){const approved=await pool.query(`SELECT 1 FROM estimates WHERE work_order_id=$1 AND status='approved' LIMIT 1`,[req.params.id]);if(!approved.rowCount)throw new Error('Prima di avviare la riparazione serve un preventivo approvato.');}await pool.query('UPDATE work_orders SET status=$1,updated_at=now() WHERE id=$2',[target,req.params.id]);await pool.query('INSERT INTO audit_log(user_id,action,entity_type,entity_id,details) VALUES($1,$2,$3,$4,$5)',[req.session.user.id,'status_change','work_order',String(req.params.id),JSON.stringify({from:w.rows[0].status,to:target})]);flash(req,'Stato aggiornato.');res.redirect(`/work-orders/${req.params.id}`);}catch(e){flash(req,e.message);res.redirect(`/work-orders/${req.params.id}`);}});
app.post('/work-orders/:id/quality-checks/setup',needAuth,allow('owner','admin','manager','mechanic'),async(req,res,next)=>{try{const w=await pool.query('SELECT id FROM work_orders WHERE id=$1',[req.params.id]);if(!w.rowCount)return res.sendStatus(404);const labels=['Serraggi verificati','Livelli controllati','Spie e anomalie verificate','Perdite assenti','Lavorazioni richieste completate','Area di lavoro e veicolo controllati'];for(const label of labels)await pool.query(`INSERT INTO quality_checks(work_order_id,label) SELECT $1,$2 WHERE NOT EXISTS (SELECT 1 FROM quality_checks WHERE work_order_id=$1 AND label=$2)`,[req.params.id,label]);flash(req,'Checklist controllo qualità pronta.');res.redirect(`/work-orders/${req.params.id}`);}catch(e){next(e);}});
app.post('/work-orders/:id/photos',needAuth,allow('owner','admin','manager','reception','mechanic'),async(req,res,next)=>{const files=req.files||[];const c=await pool.connect();try{if(!files.length)throw new Error('Seleziona almeno una foto.');await c.query('BEGIN');const order=await c.query('SELECT id FROM work_orders WHERE id=$1 FOR UPDATE',[req.params.id]);if(!order.rowCount)throw new Error('Ordine di lavoro non trovato.');for(const f of files){const png=f.mimetype==='image/png'&&f.buffer.subarray(0,8).equals(Buffer.from([137,80,78,71,13,10,26,10]));const jpeg=f.mimetype==='image/jpeg'&&f.buffer[0]===0xff&&f.buffer[1]===0xd8&&f.buffer[2]===0xff;if(!png&&!jpeg)throw new Error('Sono ammesse solo immagini PNG e JPEG valide.');const name=path.basename(f.originalname).slice(0,180)||'foto-veicolo';await c.query(`INSERT INTO documents(work_order_id,document_type,file_name,mime_type,file_data,created_by) VALUES($1,'vehicle_photo',$2,$3,$4,$5)`,[req.params.id,name,f.mimetype,f.buffer,req.session.user.id]);}await c.query(`INSERT INTO audit_log(user_id,action,entity_type,entity_id,details) VALUES($1,'upload_photos','work_order',$2,$3)`,[req.session.user.id,String(req.params.id),JSON.stringify({count:files.length})]);await c.query('COMMIT');flash(req,`${files.length} foto salvate nel database.`);res.redirect(`/work-orders/${req.params.id}`);}catch(e){await c.query('ROLLBACK');flash(req,e.message);res.redirect(`/work-orders/${req.params.id}`);}finally{c.release();}});
app.post('/work-orders/:id/acceptance',needAuth,allow('owner','admin','manager','reception'),async(req,res,next)=>{const c=await pool.connect();try{const name=String(req.body.accepted_by||'').trim();const acceptsTerms=req.body.accept_terms==='yes',ackPrivacy=req.body.ack_privacy==='yes';if(!name||(!acceptsTerms&&!ackPrivacy))throw new Error('Inserisci il nome e seleziona il documento confermato.');await c.query('BEGIN');const order=await c.query('SELECT id,customer_id FROM work_orders WHERE id=$1 FOR UPDATE',[req.params.id]);if(!order.rowCount)throw new Error('Ordine di lavoro non trovato.');const s=await c.query('SELECT repair_terms,privacy_notice FROM workshop_settings WHERE id=1');const templates=s.rows[0];const values=[['repair_terms',acceptsTerms?templates.repair_terms:null,req.body.terms_version],['privacy_notice',ackPrivacy?templates.privacy_notice:null,req.body.privacy_version]];for(const [type,content,postedVersion] of values){if(content===null)continue;if(!String(content||'').trim())throw new Error('Configura il testo del documento prima di registrare la presa visione.');const version=crypto.createHash('sha256').update(content).digest('hex');if(version!==postedVersion)throw new Error('I testi sono cambiati. Ricarica la scheda e verifica la versione corrente.');await c.query(`INSERT INTO document_acceptances(work_order_id,customer_id,document_type,document_version,accepted,accepted_by,evidence,user_id) VALUES($1,$2,$3,$4,true,$5,$6,$7)`,[req.params.id,order.rows[0].customer_id,type,version,name,JSON.stringify({method:'recorded_in_workshop_by_operator',text_snapshot:content}),req.session.user.id]);}await c.query(`INSERT INTO audit_log(user_id,action,entity_type,entity_id,details) VALUES($1,'document_acceptance','work_order',$2,$3)`,[req.session.user.id,String(req.params.id),JSON.stringify({repair_terms:acceptsTerms,privacy_notice:ackPrivacy})]);await c.query('COMMIT');flash(req,'Presa visione registrata con versione e copia del testo mostrato.');res.redirect(`/work-orders/${req.params.id}`);}catch(e){await c.query('ROLLBACK');flash(req,e.message);res.redirect(`/work-orders/${req.params.id}`);}finally{c.release();}});
app.get('/work-orders/:id/documents/:docid',needAuth,allow('owner','admin','manager','reception','mechanic'),async(req,res,next)=>{try{const d=await pool.query(`SELECT file_name,mime_type,file_data FROM documents WHERE id=$1 AND work_order_id=$2 AND document_type='vehicle_photo'`,[req.params.docid,req.params.id]);if(!d.rowCount)return res.sendStatus(404);res.setHeader('Content-Disposition',`inline; filename="${d.rows[0].file_name.replace(/["\\\r\n]/g,'_')}"`);res.type(d.rows[0].mime_type).send(d.rows[0].file_data);}catch(e){next(e);}});
app.post('/quality-checks/:id',needAuth,allow('owner','admin','manager','mechanic'),async(req,res,next)=>{try{if(!['true','false'].includes(req.body.passed))throw new Error('Seleziona un esito valido.');const r=await pool.query(`UPDATE quality_checks SET passed=$1,note=$2,checked_by=$3,checked_at=now() WHERE id=$4 AND work_order_id=$5 RETURNING id`,[req.body.passed==='true',req.body.note||'',req.session.user.id,req.params.id,req.body.work_order_id]);if(!r.rowCount)return res.sendStatus(404);flash(req,'Controllo qualità registrato.');res.redirect(`/work-orders/${req.body.work_order_id}`);}catch(e){next(e);}});
app.post('/work-orders/:id/road-tests',needAuth,allow('owner','admin','manager'),async(req,res,next)=>{try{const start=Number(req.body.mileage_start),end=Number(req.body.mileage_end);if(!Number.isInteger(start)||!Number.isInteger(end)||end<start)throw new Error('I chilometri del test non sono validi.');if(!['passed','failed'].includes(req.body.result))throw new Error('Esito test non valido.');await pool.query(`INSERT INTO road_tests(work_order_id,driver_id,mileage_start,mileage_end,result,notes) VALUES($1,$2,$3,$4,$5,$6)`,[req.params.id,req.session.user.id,start,end,req.body.result,req.body.notes||'']);flash(req,'Test su strada registrato.');res.redirect(`/work-orders/${req.params.id}`);}catch(e){flash(req,e.message);res.redirect(`/work-orders/${req.params.id}`);}});
app.post('/work-orders/:id/mark-ready',needAuth,allow('owner','admin','manager'),async(req,res,next)=>{try{const checks=await pool.query('SELECT count(*)::int AS total,count(*) FILTER (WHERE passed IS TRUE)::int AS passed FROM quality_checks WHERE work_order_id=$1',[req.params.id]);const test=await pool.query('SELECT result FROM road_tests WHERE work_order_id=$1 ORDER BY tested_at DESC LIMIT 1',[req.params.id]);if(checks.rows[0].total<6||checks.rows[0].total!==checks.rows[0].passed||test.rows[0]?.result!=='passed')throw new Error('Completa tutti i controlli e registra un test superato prima di segnare l’auto pronta.');await pool.query(`UPDATE work_orders SET status='ready',updated_at=now() WHERE id=$1`,[req.params.id]);await pool.query('INSERT INTO audit_log(user_id,action,entity_type,entity_id) VALUES($1,$2,$3,$4)',[req.session.user.id,'mark_ready','work_order',String(req.params.id)]);flash(req,'Veicolo segnato come pronto.');res.redirect(`/work-orders/${req.params.id}`);}catch(e){flash(req,e.message);res.redirect(`/work-orders/${req.params.id}`);}});
app.post('/work-orders/:id/operations',needAuth,async(req,res,next)=>{try{await pool.query('INSERT INTO work_operations(work_order_id,title,description) VALUES($1,$2,$3)',[req.params.id,req.body.title,req.body.description||'']);flash(req,'Operazione aggiunta.');res.redirect(`/work-orders/${req.params.id}`);}catch(e){next(e);}});
app.post('/operations/:id/timer/start',needAuth,allow('owner','admin','manager','mechanic'),async(req,res,next)=>{try{const op=await pool.query(`SELECT o.work_order_id,(o.id=(SELECT min(id) FROM work_operations WHERE work_order_id=o.work_order_id) AND o.title='Diagnosi iniziale') AS diagnosis_only FROM work_operations o WHERE o.id=$1`,[req.params.id]);if(!op.rowCount)return res.sendStatus(404);if(req.session.user.role==='mechanic'){const assigned=await pool.query('SELECT 1 FROM operation_assignments WHERE operation_id=$1 AND user_id=$2',[req.params.id,req.session.user.id]);if(!assigned.rowCount)throw new Error('Il timer è disponibile ai meccanici assegnati alla lavorazione.');}if(!op.rows[0].diagnosis_only){const approved=await pool.query(`SELECT 1 FROM estimates WHERE work_order_id=$1 AND status='approved' LIMIT 1`,[op.rows[0].work_order_id]);if(!approved.rowCount){flash(req,'Per avviare questa riparazione serve un preventivo approvato.');return res.redirect(req.get('Referrer')||'/work-orders');}}await pool.query('INSERT INTO time_entries(operation_id,user_id) VALUES($1,$2)',[req.params.id,req.session.user.id]);await pool.query(`UPDATE work_operations SET status='in_progress' WHERE id=$1`,[req.params.id]);if(!op.rows[0].diagnosis_only)await pool.query(`UPDATE work_orders SET status='in_progress',updated_at=now() WHERE id=$1`,[op.rows[0].work_order_id]);flash(req,'Timer avviato.');res.redirect(req.get('Referrer')||'/work-orders');}catch(e){if(e.code==='23505'){flash(req,'Hai già un timer attivo. Fermalo prima di iniziarne un altro.');return res.redirect(req.get('Referrer')||'/work-orders');}if(e.message.includes('timer è disponibile')){flash(req,e.message);return res.redirect(req.get('Referrer')||'/work-orders');}next(e);}});
app.post('/operations/:id/timer/pause',needAuth,async(req,res,next)=>{try{const r=await pool.query(`UPDATE time_entries SET paused_at=now(),note=concat_ws(E'\\n',nullif(note,''),$3) WHERE operation_id=$1 AND user_id=$2 AND stopped_at IS NULL AND paused_at IS NULL RETURNING id`,[req.params.id,req.session.user.id,req.body.reason||'Pausa']);flash(req,r.rowCount?'Timer messo in pausa.':'Non hai un timer attivo da mettere in pausa.');res.redirect(req.get('Referrer')||'/work-orders');}catch(e){next(e);}});
app.post('/operations/:id/timer/resume',needAuth,async(req,res,next)=>{try{const r=await pool.query(`UPDATE time_entries SET pause_seconds=pause_seconds+extract(epoch from now()-paused_at)::int,paused_at=NULL WHERE operation_id=$1 AND user_id=$2 AND stopped_at IS NULL AND paused_at IS NOT NULL RETURNING id`,[req.params.id,req.session.user.id]);flash(req,r.rowCount?'Timer ripreso.':'Non hai un timer in pausa su questa operazione.');res.redirect(req.get('Referrer')||'/work-orders');}catch(e){next(e);}});
app.post('/operations/:id/timer/stop',needAuth,async(req,res,next)=>{try{const r=await pool.query(`UPDATE time_entries SET pause_seconds=pause_seconds+CASE WHEN paused_at IS NULL THEN 0 ELSE extract(epoch from now()-paused_at)::int END,paused_at=NULL,stopped_at=now() WHERE operation_id=$1 AND user_id=$2 AND stopped_at IS NULL RETURNING id`,[req.params.id,req.session.user.id]);flash(req,r.rowCount?'Timer terminato.':'Non hai un timer attivo su questa operazione.');res.redirect(req.get('Referrer')||'/work-orders');}catch(e){next(e);}});
app.post('/operations/:id/assign',needAuth,allow('owner','admin','manager'),async(req,res,next)=>{const c=await pool.connect();try{await c.query('BEGIN');const ids=Array.isArray(req.body.user_ids)?req.body.user_ids:req.body.user_ids?[req.body.user_ids]:[];if(ids.length){const valid=await c.query(`SELECT count(*)::int AS n FROM users WHERE id=ANY($1::bigint[]) AND role='mechanic' AND active=true`,[ids]);if(valid.rows[0].n!==ids.length)throw new Error('Puoi assegnare solo meccanici attivi.');}await c.query('DELETE FROM operation_assignments WHERE operation_id=$1',[req.params.id]);for(let i=0;i<ids.length;i++)await c.query('INSERT INTO operation_assignments(operation_id,user_id,is_lead) VALUES($1,$2,$3)',[req.params.id,ids[i],i===0]);await c.query('COMMIT');flash(req,'Assegnazioni aggiornate.');res.redirect(req.get('Referrer')||'/work-orders');}catch(e){await c.query('ROLLBACK');flash(req,e.message);res.redirect(req.get('Referrer')||'/work-orders');}finally{c.release();}});

app.get('/team',needAuth,allow('owner','admin','manager'),async(req,res,next)=>{try{const r=await pool.query('SELECT id,name,email,role,active,created_at FROM users ORDER BY name');const rows=r.rows.map(u=>`<tr><td>${esc(u.name)}</td><td>${esc(u.email)}</td><td>${esc(u.role)}</td><td>${u.active?'<span class="badge good">Attivo</span>':'<span class="badge">Disattivato</span>'}</td><td>${fmtDate(u.created_at)}</td></tr>`).join('')||'<tr><td colspan="5" class="empty">Nessun utente</td></tr>';res.send(page('Utenti e meccanici',`${takeFlash(req)}<section class="card"><div class="section-heading"><p class="muted">Account individuali e ruoli del personale.</p><a class="button primary" href="/team/new">Aggiungi utente</a></div><div class="table-wrap"><table><thead><tr><th>Nome</th><th>Email</th><th>Ruolo</th><th>Stato</th><th>Creato</th></tr></thead><tbody>${rows}</tbody></table></div></section>`,req.session.user,'team'));}catch(e){next(e);}});
app.get('/team/new',needAuth,allow('owner','admin'),(req,res)=>res.send(page('Nuovo utente',`<section class="card"><form method="post" action="/team">${formToken(req)}<div class="form-grid">${input('Nome','name','text','',true)}${input('Email','email','email','',true)}${input('Password iniziale (almeno 12 caratteri)','password','password','',true)}${select('Ruolo','role',[['manager','Responsabile officina'],['reception','Accettatore'],['mechanic','Meccanico'],['warehouse','Magazziniere'],['accounting','Amministrazione'],['accountant','Commercialista'],['admin','Amministratore']])}</div><button class="button primary">Crea account</button></form></section>`,req.session.user,'team')));
app.post('/team',needAuth,allow('owner','admin'),async(req,res,next)=>{try{if(String(req.body.password||'').length<12)throw new Error('La password iniziale deve contenere almeno 12 caratteri.');const allowed=['manager','reception','mechanic','warehouse','accounting','accountant','admin'];if(!allowed.includes(req.body.role))throw new Error('Ruolo non valido.');const hash=await bcrypt.hash(req.body.password,12);const r=await pool.query('INSERT INTO users(name,email,password_hash,role) VALUES($1,$2,$3,$4) RETURNING id',[req.body.name,req.body.email,hash,req.body.role]);await pool.query('INSERT INTO audit_log(user_id,action,entity_type,entity_id) VALUES($1,$2,$3,$4)',[req.session.user.id,'create','user',String(r.rows[0].id)]);flash(req,'Utente creato.');res.redirect('/team');}catch(e){if(e.code==='23505'){flash(req,'Esiste già un account con questa email.');return res.redirect('/team/new');}if(e.message.includes('password')||e.message.includes('Ruolo')){flash(req,e.message);return res.redirect('/team/new');}next(e);}});

app.get('/work-orders/:id/estimate/new',needAuth,async(req,res,next)=>{try{const w=await pool.query('SELECT id FROM work_orders WHERE id=$1',[req.params.id]);if(!w.rowCount)return res.sendStatus(404);const s=(await pool.query('SELECT hourly_rate FROM workshop_settings WHERE id=1')).rows[0];res.send(page(`Nuovo preventivo · GO-${req.params.id}`,`<section class="card"><p class="muted">Crea una bozza. Verifica le righe e registra l’approvazione del cliente nella scheda ordine prima di avviare le riparazioni.</p><form method="post" action="/work-orders/${req.params.id}/estimate">${formToken(req)}<div id="estimate-lines"><div class="estimate-line"><select name="line_kind"><option value="labor">Manodopera</option><option value="part">Ricambio</option><option value="service">Servizio</option></select><input name="line_description" placeholder="Descrizione operazione o ricambio" required><input name="line_quantity" type="number" step="0.01" min="0.01" value="1" required><input name="line_unit_price" type="number" step="0.01" min="0" value="${esc(s.hourly_rate)}" required><input name="line_vat_rate" type="number" step="0.01" min="0" value="22" required></div></div><button class="button" type="button" id="add-estimate-line">Aggiungi riga</button><div class="form-grid">${input('Valido fino al','valid_until','date')}${input('Note e condizioni','notes')}</div><button class="button primary">Salva bozza preventivo</button></form></section>`,req.session.user,'orders'));}catch(e){next(e);}});
app.post('/work-orders/:id/estimate',needAuth,async(req,res,next)=>{const c=await pool.connect();try{await c.query('BEGIN');const w=await c.query('SELECT id FROM work_orders WHERE id=$1 FOR UPDATE',[req.params.id]);if(!w.rowCount)throw new Error('Ordine di lavoro non trovato');const n=await c.query('SELECT coalesce(max(version),0)+1 AS version FROM estimates WHERE work_order_id=$1',[req.params.id]);const e=await c.query(`INSERT INTO estimates(work_order_id,version,status,valid_until,notes) VALUES($1,$2,'draft',$3,$4) RETURNING id`,[req.params.id,n.rows[0].version,req.body.valid_until||null,req.body.notes||'']);const kinds=Array.isArray(req.body.line_kind)?req.body.line_kind:[req.body.line_kind];const desc=Array.isArray(req.body.line_description)?req.body.line_description:[req.body.line_description];const qty=Array.isArray(req.body.line_quantity)?req.body.line_quantity:[req.body.line_quantity];const price=Array.isArray(req.body.line_unit_price)?req.body.line_unit_price:[req.body.line_unit_price];const vat=Array.isArray(req.body.line_vat_rate)?req.body.line_vat_rate:[req.body.line_vat_rate];for(let i=0;i<desc.length;i++){if(!String(desc[i]||'').trim())continue;await c.query(`INSERT INTO estimate_lines(estimate_id,kind,description,quantity,unit_price,vat_rate) VALUES($1,$2,$3,$4,$5,$6)`,[e.rows[0].id,kinds[i]||'service',desc[i],qty[i]||1,price[i]||0,vat[i]||22]);}await c.query('COMMIT');flash(req,'Bozza preventivo salvata.');res.redirect(`/work-orders/${req.params.id}`);}catch(e){await c.query('ROLLBACK');next(e);}finally{c.release();}});
app.post('/estimates/:id/decision',needAuth,async(req,res,next)=>{try{const status=req.body.decision==='approved'?'approved':req.body.decision==='rejected'?'rejected':null;if(!status)throw new Error('Decisione non valida');const e=await pool.query('UPDATE estimates SET status=$1 WHERE id=$2 RETURNING work_order_id,version',[status,req.params.id]);if(!e.rowCount)return res.sendStatus(404);if(status==='approved')await pool.query(`UPDATE work_orders SET status='scheduled',updated_at=now() WHERE id=$1`,[e.rows[0].work_order_id]);else await pool.query(`UPDATE work_orders SET status='quote_pending',updated_at=now() WHERE id=$1`,[e.rows[0].work_order_id]);await pool.query(`INSERT INTO audit_log(user_id,action,entity_type,entity_id,details) VALUES($1,$2,'estimate',$3,$4)`,[req.session.user.id,status,String(req.params.id),JSON.stringify({version:e.rows[0].version})]);flash(req,status==='approved'?'Preventivo approvato.':'Preventivo rifiutato.');res.redirect(`/work-orders/${e.rows[0].work_order_id}`);}catch(e){next(e);}});
app.get('/estimates/:id/pdf',needAuth,async(req,res,next)=>{try{const e=await pool.query(`SELECT e.*,w.id AS order_id,c.name AS customer,v.plate,v.make,v.model,s.business_name,s.address,s.phone AS workshop_phone,s.email AS workshop_email,s.vat_number,s.logo_data FROM estimates e JOIN work_orders w ON w.id=e.work_order_id JOIN customers c ON c.id=w.customer_id JOIN vehicles v ON v.id=w.vehicle_id CROSS JOIN workshop_settings s WHERE e.id=$1`,[req.params.id]);if(!e.rowCount)return res.sendStatus(404);const lines=await pool.query('SELECT * FROM estimate_lines WHERE estimate_id=$1 ORDER BY id',[req.params.id]);const d=e.rows[0];res.setHeader('Content-Type','application/pdf');res.setHeader('Content-Disposition',`inline; filename="GO-Preventivo-${d.order_id}-v${d.version}.pdf"`);const pdf=new PDFDocument({size:'A4',margin:48});pdf.pipe(res);drawWorkshopLogo(pdf,d.logo_data);pdf.fillColor('#202a39').fontSize(20).font('Helvetica-Bold').text(d.business_name,205,48,{width:342});pdf.fontSize(9).font('Helvetica').fillColor('#667085').text([d.address,d.workshop_phone,d.workshop_email,d.vat_number?`P. IVA ${d.vat_number}`:''].filter(Boolean).join(' · '),205,74,{width:342});pdf.y=115;pdf.strokeColor('#ef6b22').lineWidth(2).moveTo(48,pdf.y).lineTo(547,pdf.y).stroke();pdf.moveDown().fillColor('#202a39').fontSize(17).font('Helvetica-Bold').text(`PREVENTIVO GO-${d.order_id} · v${d.version}`);pdf.moveDown().fontSize(11).font('Helvetica').text(`Cliente: ${d.customer}`).text(`Veicolo: ${d.plate} · ${d.make} ${d.model}`).text(`Stato: ${d.status}`).text(`Validità: ${fmtDate(d.valid_until)}`);pdf.moveDown().font('Helvetica-Bold').text('Descrizione                         Q.tà       Prezzo       IVA        Totale');let net=0,tax=0;for(const l of lines.rows){const base=Number(l.quantity)*Number(l.unit_price);const iva=base*Number(l.vat_rate)/100;net+=base;tax+=iva;pdf.font('Helvetica').fontSize(10).text(`${l.description} · ${l.kind}       ${l.quantity}       ${money(l.unit_price)}       ${l.vat_rate}%       ${money(base+iva)}`);}pdf.moveDown().font('Helvetica-Bold').text(`Imponibile: ${money(net)}`).text(`IVA: ${money(tax)}`).text(`Totale preventivo: ${money(net+tax)}`);if(d.notes)pdf.moveDown().font('Helvetica').text(`Note: ${d.notes}`);pdf.moveDown(2).font('Helvetica').text('Approvazione cliente: __________________________     Data: ____ / ____ / ______');pdf.end();}catch(e){next(e);}});

app.get('/invoices',needAuth,allow('owner','admin','manager','accounting','accountant'),async(req,res,next)=>{try{const r=await pool.query(`SELECT i.*,c.name AS customer,v.plate,coalesce(sum(p.amount),0) AS paid FROM invoices i JOIN work_orders w ON w.id=i.work_order_id JOIN customers c ON c.id=w.customer_id JOIN vehicles v ON v.id=w.vehicle_id LEFT JOIN payments p ON p.invoice_id=i.id GROUP BY i.id,c.name,v.plate ORDER BY i.created_at DESC LIMIT 300`);const rows=await Promise.all(r.rows.map(async i=>{const total=await pool.query(`SELECT coalesce(sum(quantity*unit_price*(1+vat_rate/100)),0)::numeric AS amount FROM invoice_lines WHERE invoice_id=$1`,[i.id]);const due=Number(total.rows[0].amount);return `<tr><td><a href="/invoices/${i.id}">${esc(i.invoice_number)}</a></td><td>${esc(i.customer)}</td><td>${esc(i.plate)}</td><td>${fmtDate(i.issue_date)}</td><td>${money(due)}</td><td>${money(i.paid)}</td><td><span class="badge">${esc(i.status)}</span></td></tr>`;}));res.send(page('Fatture e pagamenti',`${takeFlash(req)}<section class="card"><p class="muted">Documenti gestionali e pagamenti registrati. L’emissione fiscale richiede l’integrazione con il sistema configurato dall’officina.</p><div class="table-wrap"><table><thead><tr><th>Numero</th><th>Cliente</th><th>Targa</th><th>Data</th><th>Totale</th><th>Pagato</th><th>Stato</th></tr></thead><tbody>${rows.join('')||'<tr><td colspan="7" class="empty">Nessun documento</td></tr>'}</tbody></table></div></section>`,req.session.user,'invoices'));}catch(e){next(e);}});
app.get('/invoices/:id',needAuth,allow('owner','admin','manager','accounting','accountant'),async(req,res,next)=>{try{const q=await pool.query(`SELECT i.*,c.name AS customer,v.plate,v.make,v.model FROM invoices i JOIN work_orders w ON w.id=i.work_order_id JOIN customers c ON c.id=w.customer_id JOIN vehicles v ON v.id=w.vehicle_id WHERE i.id=$1`,[req.params.id]);if(!q.rowCount)return res.sendStatus(404);const i=q.rows[0];const [lines,pays,total]=await Promise.all([pool.query('SELECT * FROM invoice_lines WHERE invoice_id=$1 ORDER BY id',[i.id]),pool.query('SELECT * FROM payments WHERE invoice_id=$1 ORDER BY paid_at',[i.id]),pool.query('SELECT coalesce(sum(quantity*unit_price*(1+vat_rate/100)),0)::numeric AS amount FROM invoice_lines WHERE invoice_id=$1',[i.id])]);const grand=Number(total.rows[0].amount),paid=pays.rows.reduce((n,p)=>n+Number(p.amount),0),due=Math.max(0,grand-paid);const lineRows=lines.rows.map(l=>`<tr><td>${esc(l.description)}</td><td>${Number(l.quantity)}</td><td>${money(l.unit_price)}</td><td>${l.vat_rate}%</td><td>${money(Number(l.quantity)*Number(l.unit_price)*(1+Number(l.vat_rate)/100))}</td></tr>`).join('');const payRows=pays.rows.map(p=>`<tr><td>${fmtDate(p.paid_at)}</td><td>${esc(p.method)}</td><td>${money(p.amount)}</td><td>${esc(p.reference)}</td></tr>`).join('')||'<tr><td colspan="4" class="empty">Nessun pagamento</td></tr>';const body=`${takeFlash(req)}<section class="card"><div class="section-heading"><div><span class="eyebrow">DOCUMENTO GESTIONALE · NON FISCALE</span><h2>${esc(i.invoice_number)}</h2><p class="muted">${esc(i.customer)} · ${esc(i.plate)} ${esc(i.make)} ${esc(i.model)}</p></div><a class="button" href="/invoices/${i.id}/pdf">PDF stampabile</a></div><div class="table-wrap"><table><thead><tr><th>Descrizione</th><th>Q.tà</th><th>Prezzo</th><th>IVA</th><th>Totale riga</th></tr></thead><tbody>${lineRows}</tbody></table></div><div class="totals"><strong>Totale: ${money(grand)}</strong><strong>Pagato: ${money(paid)}</strong><strong>Residuo: ${money(due)}</strong></div>${i.status==='draft'?`<form method="post" action="/invoices/${i.id}/issue">${formToken(req)}<button class="button primary">Conferma documento gestionale</button></form>`:''}</section><section class="card"><h2>Pagamenti</h2><div class="table-wrap"><table><thead><tr><th>Data</th><th>Metodo</th><th>Importo</th><th>Riferimento</th></tr></thead><tbody>${payRows}</tbody></table></div>${due>0&&i.status!=='draft'&&i.status!=='void'?`<form class="inline-form" method="post" action="/invoices/${i.id}/payments">${formToken(req)}${input('Importo (€)','amount','number',due.toFixed(2),true)}${select('Metodo','method',[['cash','Contanti'],['card','Carta'],['bank_transfer','Bonifico'],['other','Altro']])}${input('Riferimento','reference')}<button class="button primary">Registra pagamento</button></form>`:''}</section><section class="card"><form method="post" action="/work-orders/${i.work_order_id}/deliver">${formToken(req)}<h2>Consegna veicolo</h2><div class="form-grid">${input('Consegnato a','received_by','text','',true)}${input('Km alla consegna','mileage_out','number','0')}</div><label>Note consegna<textarea name="notes"></textarea></label><button class="button primary" ${due>0||i.status==='draft'?'disabled title="Conferma il documento e registra prima il saldo completo"':''}>Registra consegna</button><p class="muted">La consegna si abilita quando il residuo è saldato.</p></form></section>`;res.send(page(`Documento ${i.invoice_number}`,body,req.session.user,'invoices'));}catch(e){next(e);}});
app.post('/work-orders/:id/invoice',needAuth,allow('owner','admin','accounting'),async(req,res,next)=>{const c=await pool.connect();try{await c.query('BEGIN');const w=await c.query(`SELECT w.id,w.status FROM work_orders w WHERE w.id=$1 FOR UPDATE`,[req.params.id]);if(!w.rowCount)throw new Error('Ordine non trovato.');if(w.rows[0].status!=='ready')throw new Error('Il documento può essere preparato dopo il superamento dei controlli e del test.');const approved=await c.query(`SELECT id FROM estimates WHERE work_order_id=$1 AND status='approved' ORDER BY version DESC LIMIT 1`,[req.params.id]);if(!approved.rowCount)throw new Error('Serve un preventivo approvato.');const existing=await c.query(`SELECT id FROM invoices WHERE work_order_id=$1 AND status<>'void'`,[req.params.id]);if(existing.rowCount)throw new Error('Esiste già un documento per questo ordine.');const number=`GO-${new Date().getFullYear()}-${String(req.params.id).padStart(6,'0')}`;const inv=await c.query(`INSERT INTO invoices(work_order_id,invoice_number,status,created_by) VALUES($1,$2,'draft',$3) RETURNING id`,[req.params.id,number,req.session.user.id]);await c.query(`INSERT INTO invoice_lines(invoice_id,kind,description,quantity,unit_price,vat_rate) SELECT $1,kind,description,quantity,unit_price,vat_rate FROM estimate_lines WHERE estimate_id=$2`,[inv.rows[0].id,approved.rows[0].id]);await c.query('COMMIT');res.redirect(`/invoices/${inv.rows[0].id}`);}catch(e){await c.query('ROLLBACK');flash(req,e.message);res.redirect(`/work-orders/${req.params.id}`);}finally{c.release();}});
app.post('/invoices/:id/issue',needAuth,allow('owner','admin','accounting'),async(req,res,next)=>{const c=await pool.connect();try{await c.query('BEGIN');const r=await c.query(`UPDATE invoices SET status='open' WHERE id=$1 AND status='draft' RETURNING work_order_id`,[req.params.id]);if(!r.rowCount)throw new Error('Documento non trovato o già confermato.');await c.query(`UPDATE work_orders SET status='invoiced',updated_at=now() WHERE id=$1 AND status='ready'`,[r.rows[0].work_order_id]);await c.query('COMMIT');flash(req,'Documento gestionale confermato come aperto. Non è un’emissione fiscale.');res.redirect(`/invoices/${req.params.id}`);}catch(e){await c.query('ROLLBACK');flash(req,e.message);res.redirect(`/invoices/${req.params.id}`);}finally{c.release();}});
app.post('/invoices/:id/payments',needAuth,allow('owner','admin','accounting'),async(req,res,next)=>{const c=await pool.connect();try{await c.query('BEGIN');const inv=await c.query('SELECT id FROM invoices WHERE id=$1 AND status IN (\'open\',\'partial\') FOR UPDATE',[req.params.id]);if(!inv.rowCount)throw new Error('Il documento non è aperto ai pagamenti.');const total=await c.query(`SELECT coalesce(sum(quantity*unit_price*(1+vat_rate/100)),0) AS amount FROM invoice_lines WHERE invoice_id=$1`,[req.params.id]);const paid=await c.query('SELECT coalesce(sum(amount),0) AS amount FROM payments WHERE invoice_id=$1',[req.params.id]);const amount=Number(req.body.amount),due=Number(total.rows[0].amount)-Number(paid.rows[0].amount);if(!Number.isFinite(amount)||amount<=0||amount>due+.005)throw new Error('Importo non valido o superiore al residuo.');await c.query('INSERT INTO payments(invoice_id,amount,method,reference,created_by) VALUES($1,$2,$3,$4,$5)',[req.params.id,amount,req.body.method,req.body.reference||'',req.session.user.id]);const newPaid=Number(paid.rows[0].amount)+amount;await c.query('UPDATE invoices SET status=$1 WHERE id=$2',[newPaid+.005>=Number(total.rows[0].amount)?'paid':'partial',req.params.id]);await c.query('COMMIT');flash(req,'Pagamento registrato.');res.redirect(`/invoices/${req.params.id}`);}catch(e){await c.query('ROLLBACK');flash(req,e.message);res.redirect(`/invoices/${req.params.id}`);}finally{c.release();}});
app.post('/work-orders/:id/deliver',needAuth,allow('owner','admin','manager','reception'),async(req,res,next)=>{const c=await pool.connect();try{await c.query('BEGIN');const w=await c.query('SELECT id,vehicle_id,status FROM work_orders WHERE id=$1 FOR UPDATE',[req.params.id]);if(!w.rowCount)throw new Error('Ordine non trovato.');if(w.rows[0].status!=='invoiced')throw new Error('L’ordine deve superare i controlli ed essere documentato prima della consegna.');const unpaid=await c.query(`SELECT 1 FROM invoices i WHERE i.work_order_id=$1 AND i.status<>'paid' AND i.status<>'void' LIMIT 1`,[req.params.id]);if(unpaid.rowCount)throw new Error('Per registrare la consegna, salda prima il documento aperto.');const missing=await c.query(`SELECT 1 FROM invoices WHERE work_order_id=$1 AND status='paid'`,[req.params.id]);if(!missing.rowCount)throw new Error('Registra il documento e il pagamento prima della consegna.');const mileage=Number(req.body.mileage_out||0);if(!Number.isInteger(mileage)||mileage<0)throw new Error('Chilometraggio non valido.');await c.query(`INSERT INTO vehicle_deliveries(work_order_id,received_by,mileage_out,notes,user_id) VALUES($1,$2,$3,$4,$5)`,[req.params.id,req.body.received_by,mileage,req.body.notes||'',req.session.user.id]);await c.query(`UPDATE work_orders SET status='delivered',updated_at=now() WHERE id=$1`,[req.params.id]);await c.query(`UPDATE vehicles SET mileage=$1 WHERE id=$2 AND $1>=mileage`,[mileage,w.rows[0].vehicle_id]);await c.query('COMMIT');flash(req,'Consegna registrata.');res.redirect(`/work-orders/${req.params.id}`);}catch(e){await c.query('ROLLBACK');flash(req,e.message);res.redirect(`/invoices`);}finally{c.release();}});
app.get('/invoices/:id/pdf',needAuth,allow('owner','admin','manager','accounting','accountant'),async(req,res,next)=>{try{const q=await pool.query(`SELECT i.*,w.id AS order_id,c.name AS customer,v.plate,v.make,v.model,s.business_name,s.address,s.phone,s.email,s.vat_number,s.logo_data FROM invoices i JOIN work_orders w ON w.id=i.work_order_id JOIN customers c ON c.id=w.customer_id JOIN vehicles v ON v.id=w.vehicle_id CROSS JOIN workshop_settings s WHERE i.id=$1`,[req.params.id]);if(!q.rowCount)return res.sendStatus(404);const d=q.rows[0],lines=await pool.query('SELECT * FROM invoice_lines WHERE invoice_id=$1 ORDER BY id',[d.id]);const pdf=new PDFDocument({size:'A4',margin:48});res.setHeader('Content-Type','application/pdf');res.setHeader('Content-Disposition',`inline; filename="${d.invoice_number}.pdf"`);pdf.pipe(res);drawWorkshopLogo(pdf,d.logo_data);pdf.fillColor('#202a39').fontSize(17).font('Helvetica-Bold').text(d.business_name,205,48,{width:342});pdf.fillColor('#667085').fontSize(8).font('Helvetica').text([d.address,d.phone,d.email,d.vat_number?`P. IVA ${d.vat_number}`:''].filter(Boolean).join(' · '),205,74,{width:342});pdf.y=115;pdf.strokeColor('#ef6b22').lineWidth(2).moveTo(48,pdf.y).lineTo(547,pdf.y).stroke();pdf.moveDown().fillColor('#202a39').fontSize(17).font('Helvetica-Bold').text('DOCUMENTO GESTIONALE · NON FISCALE');pdf.fontSize(12).font('Helvetica').text(`Numero: ${d.invoice_number}`).text(`Data: ${fmtDate(d.issue_date)}`).text(`Cliente: ${d.customer}`).text(`Veicolo: ${d.plate} · ${d.make} ${d.model}`).moveDown();let total=0;for(const l of lines.rows){const row=Number(l.quantity)*Number(l.unit_price)*(1+Number(l.vat_rate)/100);total+=row;pdf.fontSize(10).text(`${l.description} · ${l.quantity} × ${money(l.unit_price)} + IVA ${l.vat_rate}% = ${money(row)}`);}pdf.moveDown().font('Helvetica-Bold').fontSize(13).text(`Totale gestionale: ${money(total)}`);pdf.moveDown().fontSize(8).fillColor('#667085').text('Questo documento non è una fattura fiscale e non sostituisce il sistema di fatturazione elettronica configurato dall’officina.');pdf.end();}catch(e){next(e);}});
app.get('/invoices/:id/documents/:docid',needAuth,async(req,res,next)=>{try{const d=await pool.query('SELECT * FROM documents WHERE id=$1 AND invoice_id=$2',[req.params.docid,req.params.id]);if(!d.rowCount)return res.sendStatus(404);res.type(d.rows[0].mime_type).send(d.rows[0].file_data);}catch(e){next(e);}});

app.get('/inventory',needAuth,allow('owner','admin','manager','warehouse'),async(req,res,next)=>{try{const r=await pool.query(`SELECT i.*,i.quantity-coalesce((SELECT sum(quantity) FROM inventory_reservations r WHERE r.item_id=i.id AND r.status='reserved'),0) AS available,coalesce((SELECT sum(quantity) FROM inventory_reservations r WHERE r.item_id=i.id AND r.status='reserved'),0) AS reserved FROM inventory_items i ORDER BY i.description LIMIT 500`);const rows=r.rows.map(i=>`<tr><td>${esc(i.sku)}</td><td><a href="/inventory/${i.id}">${esc(i.description)}</a></td><td>${esc(i.location)}</td><td>${Number(i.quantity).toLocaleString('it-IT')}</td><td>${Number(i.reserved).toLocaleString('it-IT')}</td><td>${Number(i.available).toLocaleString('it-IT')}</td><td>${Number(i.minimum_quantity).toLocaleString('it-IT')}</td><td>${money(i.unit_cost)}</td><td>${Number(i.available)<=Number(i.minimum_quantity)?'<span class="badge warning">Riordinare</span>':'<span class="badge good">Disponibile</span>'}</td></tr>`).join('')||'<tr><td colspan="9" class="empty">Magazzino vuoto</td></tr>';res.send(page('Magazzino ricambi',`${takeFlash(req)}<section class="card"><div class="section-heading"><p class="muted">Giacenza fisica, riserve per commessa e quantità realmente disponibili.</p><div class="actions"><a class="button" href="/suppliers">Fornitori</a><a class="button" href="/purchases">Ordini fornitore</a><a class="button primary" href="/inventory/new">Nuovo articolo</a></div></div><div class="table-wrap"><table><thead><tr><th>Codice</th><th>Articolo</th><th>Ubicazione</th><th>Giacenza</th><th>Riservato</th><th>Disponibile</th><th>Minimo</th><th>Costo</th><th>Stato</th></tr></thead><tbody>${rows}</tbody></table></div></section>`,req.session.user,'inventory'));}catch(e){next(e);}});
app.get('/inventory/new',needAuth,allow('owner','admin','manager','warehouse'),(_req,res)=>res.send(page('Nuovo articolo',`<section class="card"><form method="post" action="/inventory">${formToken(_req)}<div class="form-grid">${input('Codice articolo','sku')}${input('Descrizione','description','text','',true)}${input('Ubicazione','location')}${input('Fornitore','supplier')}${input('Costo unitario','unit_cost','number','0')}${input('Prezzo unitario','unit_price','number','0')}${input('Giacenza iniziale','quantity','number','0')}${input('Scorta minima','minimum_quantity','number','0')}</div><button class="button primary">Crea articolo</button></form></section>`,_req.session.user,'inventory')));
app.post('/inventory',needAuth,allow('owner','admin','manager','warehouse'),async(req,res,next)=>{const c=await pool.connect();try{await c.query('BEGIN');const vals=[req.body.sku||'',req.body.description,req.body.location||'',req.body.supplier||'',req.body.unit_cost||0,req.body.unit_price||0,req.body.quantity||0,req.body.minimum_quantity||0];const r=await c.query(`INSERT INTO inventory_items(sku,description,location,supplier,unit_cost,unit_price,quantity,minimum_quantity) VALUES($1,$2,$3,$4,$5,$6,$7,$8) RETURNING id,quantity`,vals);if(Number(r.rows[0].quantity)!==0)await c.query(`INSERT INTO stock_movements(item_id,movement_type,quantity,reason,user_id) VALUES($1,'initial_load',$2,'Giacenza iniziale',$3)`,[r.rows[0].id,r.rows[0].quantity,req.session.user.id]);await c.query('COMMIT');flash(req,'Articolo creato.');res.redirect('/inventory');}catch(e){await c.query('ROLLBACK');next(e);}finally{c.release();}});
app.get('/inventory/:id',needAuth,allow('owner','admin','manager','warehouse'),async(req,res,next)=>{try{const item=await pool.query(`SELECT i.*,i.quantity-coalesce((SELECT sum(quantity) FROM inventory_reservations r WHERE r.item_id=i.id AND r.status='reserved'),0) AS available FROM inventory_items i WHERE i.id=$1`,[req.params.id]);if(!item.rowCount)return res.sendStatus(404);const i=item.rows[0];const [orders,reservations,movements]=await Promise.all([pool.query(`SELECT id FROM work_orders WHERE status NOT IN ('closed','cancelled') ORDER BY id DESC LIMIT 100`),pool.query(`SELECT r.*,w.id AS order_id,v.plate,c.name AS customer FROM inventory_reservations r JOIN work_orders w ON w.id=r.work_order_id JOIN vehicles v ON v.id=w.vehicle_id JOIN customers c ON c.id=w.customer_id WHERE r.item_id=$1 ORDER BY r.created_at DESC LIMIT 100`,[i.id]),pool.query(`SELECT m.*,u.name FROM stock_movements m LEFT JOIN users u ON u.id=m.user_id WHERE m.item_id=$1 ORDER BY m.created_at DESC LIMIT 100`,[i.id])]);const orderOpts=orders.rows.map(o=>[o.id,`GO-${o.id}`]);const resRows=reservations.rows.map(r=>`<tr><td><a href="/work-orders/${r.order_id}">GO-${r.order_id} · ${esc(r.plate)}</a></td><td>${Number(r.quantity)}</td><td>${esc(r.status)}</td><td>${fmtDate(r.created_at)}</td><td>${r.status==='reserved'?`<form class="inline-form" method="post" action="/inventory/reservations/${r.id}/consume">${formToken(req)}<button class="button small primary">Scarica usato</button></form><form method="post" action="/inventory/reservations/${r.id}/release">${formToken(req)}<button class="button small">Annulla riserva</button></form>`:'—'}</td></tr>`).join('')||'<tr><td colspan="5" class="empty">Nessuna riserva per questo ricambio</td></tr>';const moveRows=movements.rows.map(m=>`<tr><td>${fmtDate(m.created_at)}</td><td>${esc(m.movement_type)}</td><td>${Number(m.quantity).toLocaleString('it-IT')}</td><td>${esc(m.reason)}</td><td>${esc(m.name||'—')}</td></tr>`).join('')||'<tr><td colspan="5" class="empty">Nessun movimento</td></tr>';res.send(page(i.description,`${takeFlash(req)}<section class="card"><div class="detail-grid"><div><span class="muted">Codice</span><strong>${esc(i.sku||'—')}</strong></div><div><span class="muted">Giacenza fisica</span><strong>${Number(i.quantity)}</strong></div><div><span class="muted">Disponibile</span><strong>${Number(i.available)}</strong></div><div><span class="muted">Ubicazione</span><strong>${esc(i.location||'—')}</strong></div></div><form class="inline-form" method="post" action="/inventory/${i.id}/reservations">${formToken(req)}${select('Ordine di lavoro','work_order_id',orderOpts)}${input('Quantità da riservare','quantity','number','1',true)}<button class="button primary">Riserva ricambio</button></form></section><section class="card"><h2>Riserve per ordine</h2><div class="table-wrap"><table><thead><tr><th>Ordine</th><th>Quantità</th><th>Stato</th><th>Data</th><th>Azione</th></tr></thead><tbody>${resRows}</tbody></table></div></section><section class="card"><h2>Movimenti di magazzino</h2><div class="table-wrap"><table><thead><tr><th>Data</th><th>Tipo</th><th>Quantità (+ carico, − scarico)</th><th>Motivo</th><th>Utente</th></tr></thead><tbody>${moveRows}</tbody></table></div></section>`,req.session.user,'inventory'));}catch(e){next(e);}});
app.post('/inventory/:id/reservations',needAuth,allow('owner','admin','manager','warehouse'),async(req,res,next)=>{const c=await pool.connect();try{await c.query('BEGIN');const item=await c.query('SELECT id,quantity FROM inventory_items WHERE id=$1 FOR UPDATE',[req.params.id]);if(!item.rowCount)throw new Error('Ricambio non trovato.');const qty=Number(req.body.quantity);if(!Number.isFinite(qty)||qty<=0)throw new Error('La quantità deve essere maggiore di zero.');const order=await c.query(`SELECT id FROM work_orders WHERE id=$1 AND status NOT IN ('closed','cancelled')`,[req.body.work_order_id]);if(!order.rowCount)throw new Error('Ordine di lavoro non valido o chiuso.');const reserved=await c.query(`SELECT coalesce(sum(quantity),0) AS quantity FROM inventory_reservations WHERE item_id=$1 AND status='reserved'`,[req.params.id]);if(qty>Number(item.rows[0].quantity)-Number(reserved.rows[0].quantity))throw new Error('La quantità supera la disponibilità non riservata.');const r=await c.query(`INSERT INTO inventory_reservations(item_id,work_order_id,quantity,reserved_by) VALUES($1,$2,$3,$4) RETURNING id`,[req.params.id,req.body.work_order_id,qty,req.session.user.id]);await c.query(`INSERT INTO audit_log(user_id,action,entity_type,entity_id,details) VALUES($1,'reserve','inventory_item',$2,$3)`,[req.session.user.id,String(req.params.id),JSON.stringify({reservation_id:r.rows[0].id,work_order_id:req.body.work_order_id,quantity:qty})]);await c.query('COMMIT');flash(req,'Ricambio riservato all’ordine.');res.redirect(`/inventory/${req.params.id}`);}catch(e){await c.query('ROLLBACK');flash(req,e.message);res.redirect(`/inventory/${req.params.id}`);}finally{c.release();}});
app.post('/inventory/reservations/:id/consume',needAuth,allow('owner','admin','manager','warehouse','mechanic'),async(req,res,next)=>{const c=await pool.connect();try{await c.query('BEGIN');const q=await c.query(`SELECT r.*,i.description,i.quantity AS stock FROM inventory_reservations r JOIN inventory_items i ON i.id=r.item_id WHERE r.id=$1 FOR UPDATE OF r,i`,[req.params.id]);if(!q.rowCount)throw new Error('Riserva non trovata.');const r=q.rows[0];if(r.status!=='reserved')throw new Error('La riserva non è più attiva.');if(Number(r.stock)<Number(r.quantity))throw new Error('Giacenza insufficiente: controlla i movimenti.');await c.query(`UPDATE inventory_items SET quantity=quantity-$1 WHERE id=$2`,[r.quantity,r.item_id]);await c.query(`UPDATE inventory_reservations SET status='consumed',updated_at=now() WHERE id=$1`,[r.id]);await c.query(`INSERT INTO stock_movements(item_id,work_order_id,movement_type,quantity,reason,user_id) VALUES($1,$2,'work_order_use',$3,$4,$5)`,[r.item_id,r.work_order_id,-Number(r.quantity),`Ricambio usato in GO-${r.work_order_id}`,req.session.user.id]);await c.query('COMMIT');flash(req,'Ricambio scaricato dalla giacenza e collegato all’ordine.');res.redirect(`/inventory/${r.item_id}`);}catch(e){await c.query('ROLLBACK');flash(req,e.message);res.redirect('/inventory');}finally{c.release();}});
app.post('/inventory/reservations/:id/release',needAuth,allow('owner','admin','manager','warehouse'),async(req,res,next)=>{try{const r=await pool.query(`UPDATE inventory_reservations SET status='released',updated_at=now() WHERE id=$1 AND status='reserved' RETURNING item_id`,[req.params.id]);if(!r.rowCount)throw new Error('Riserva non attiva o già chiusa.');await pool.query(`INSERT INTO audit_log(user_id,action,entity_type,entity_id) VALUES($1,'release_reservation','inventory_item',$2)`,[req.session.user.id,String(r.rows[0].item_id)]);flash(req,'Riserva annullata; la quantità è nuovamente disponibile.');res.redirect(`/inventory/${r.rows[0].item_id}`);}catch(e){flash(req,e.message);res.redirect('/inventory');}});

app.get('/suppliers',needAuth,allow('owner','admin','manager','warehouse'),async(req,res,next)=>{try{const r=await pool.query('SELECT * FROM suppliers ORDER BY name');const rows=r.rows.map(s=>`<tr><td>${esc(s.name)}</td><td>${esc(s.vat_number||'—')}</td><td>${esc(s.phone||'—')}</td><td>${esc(s.email||'—')}</td><td>${s.active?'Attivo':'Archiviato'}</td></tr>`).join('')||'<tr><td colspan="5" class="empty">Nessun fornitore registrato</td></tr>';res.send(page('Fornitori',`${takeFlash(req)}<section class="card"><div class="section-heading"><p class="muted">Anagrafica fornitori per ricambi e ordini di acquisto.</p><a class="button primary" href="/suppliers/new">Nuovo fornitore</a></div><div class="table-wrap"><table><thead><tr><th>Nome</th><th>Partita IVA</th><th>Telefono</th><th>Email</th><th>Stato</th></tr></thead><tbody>${rows}</tbody></table></div></section>`,req.session.user,'inventory'));}catch(e){next(e);}});
app.get('/suppliers/new',needAuth,allow('owner','admin','manager','warehouse'),(req,res)=>res.send(page('Nuovo fornitore',`<section class="card"><form method="post" action="/suppliers">${formToken(req)}<div class="form-grid">${input('Ragione sociale','name','text','',true)}${input('Partita IVA','vat_number')}${input('Telefono','phone','tel')}${input('Email','email','email')}${input('Indirizzo','address')}</div><label>Note<textarea name="notes"></textarea></label><button class="button primary">Salva fornitore</button></form></section>`,req.session.user,'inventory')));
app.post('/suppliers',needAuth,allow('owner','admin','manager','warehouse'),async(req,res,next)=>{try{const name=String(req.body.name||'').trim();if(!name)throw new Error('Inserisci la ragione sociale.');await pool.query('INSERT INTO suppliers(name,vat_number,phone,email,address,notes) VALUES($1,$2,$3,$4,$5,$6)',[name,req.body.vat_number||'',req.body.phone||'',req.body.email||'',req.body.address||'',req.body.notes||'']);flash(req,'Fornitore registrato.');res.redirect('/suppliers');}catch(e){flash(req,e.message);res.redirect('/suppliers/new');}});
app.get('/purchases',needAuth,allow('owner','admin','manager','warehouse'),async(req,res,next)=>{try{const r=await pool.query(`SELECT p.*,s.name AS supplier,count(l.id)::int AS lines,count(l.id) FILTER (WHERE l.quantity_received<l.quantity_ordered)::int AS open_lines FROM purchase_orders p JOIN suppliers s ON s.id=p.supplier_id LEFT JOIN purchase_order_lines l ON l.purchase_order_id=p.id GROUP BY p.id,s.name ORDER BY p.created_at DESC LIMIT 300`);const rows=r.rows.map(p=>`<tr><td><a href="/purchases/${p.id}">ACQ-${p.id}</a></td><td>${esc(p.supplier)}</td><td>${fmtDate(p.ordered_at||p.created_at)}</td><td>${p.lines}</td><td>${p.open_lines?'Parziale / in attesa':'Ricevuto'}</td></tr>`).join('')||'<tr><td colspan="5" class="empty">Nessun ordine fornitore</td></tr>';res.send(page('Ordini fornitore',`${takeFlash(req)}<section class="card"><div class="section-heading"><p class="muted">Ordini, arrivi parziali e aggiornamento automatico della giacenza.</p><a class="button primary" href="/purchases/new">Nuovo ordine</a></div><div class="table-wrap"><table><thead><tr><th>Ordine</th><th>Fornitore</th><th>Data</th><th>Righe</th><th>Ricevimento</th></tr></thead><tbody>${rows}</tbody></table></div></section>`,req.session.user,'inventory'));}catch(e){next(e);}});
app.get('/purchases/new',needAuth,allow('owner','admin','manager','warehouse'),async(req,res,next)=>{try{const [suppliers,items,orders]=await Promise.all([pool.query('SELECT id,name FROM suppliers WHERE active ORDER BY name'),pool.query('SELECT id,sku,description,unit_cost FROM inventory_items ORDER BY description'),pool.query('SELECT id FROM work_orders WHERE status NOT IN (\'closed\',\'cancelled\') ORDER BY id DESC LIMIT 100')]);const sOpts=suppliers.rows.map(s=>[s.id,s.name]);const iOpts=items.rows.map(i=>[i.id,`${i.sku?i.sku+' · ':''}${i.description}`]);const wOpts=[['','Nessuno'],...orders.rows.map(w=>[w.id,`GO-${w.id}`])];res.send(page('Nuovo ordine fornitore',`${takeFlash(req)}<section class="card"><p class="muted">L’arrivo viene registrato per quantità, anche quando il fornitore consegna l’ordine in più tranche.</p><form method="post" action="/purchases">${formToken(req)}<div class="form-grid">${select('Fornitore','supplier_id',sOpts)}${select('Ordine di lavoro collegato','work_order_id',wOpts)}</div><div id="purchase-lines"><div class="purchase-line"><select name="item_id" required>${iOpts.map(([v,l])=>`<option value="${v}">${esc(l)}</option>`).join('')}</select><input type="number" name="quantity_ordered" min="0.01" step="0.01" value="1" required aria-label="Quantità"><input type="number" name="unit_cost" min="0" step="0.01" value="0" required aria-label="Costo unitario"><button type="button" class="button small remove-line">Rimuovi</button></div></div><button class="button" id="add-purchase-line" type="button">Aggiungi articolo</button><div class="form-grid">${input('Data prevista','expected_at','date')}${input('Note','notes')}</div><button class="button primary">Registra e invia ordine</button></form></section>`,req.session.user,'inventory'));}catch(e){next(e);}});
app.post('/purchases',needAuth,allow('owner','admin','manager','warehouse'),async(req,res,next)=>{const c=await pool.connect();try{await c.query('BEGIN');const ids=Array.isArray(req.body.item_id)?req.body.item_id:[req.body.item_id];const quantities=Array.isArray(req.body.quantity_ordered)?req.body.quantity_ordered:[req.body.quantity_ordered];const costs=Array.isArray(req.body.unit_cost)?req.body.unit_cost:[req.body.unit_cost];if(!ids.length||!ids[0])throw new Error('Aggiungi almeno un ricambio.');const supplier=await c.query('SELECT id FROM suppliers WHERE id=$1 AND active=true',[req.body.supplier_id]);if(!supplier.rowCount)throw new Error('Seleziona un fornitore attivo.');const p=await c.query(`INSERT INTO purchase_orders(supplier_id,work_order_id,status,ordered_at,expected_at,notes,created_by) VALUES($1,$2,'ordered',now(),$3,$4,$5) RETURNING id`,[req.body.supplier_id,req.body.work_order_id||null,req.body.expected_at||null,req.body.notes||'',req.session.user.id]);for(let i=0;i<ids.length;i++){const qty=Number(quantities[i]),cost=Number(costs[i]);if(!Number.isFinite(qty)||qty<=0||!Number.isFinite(cost)||cost<0)throw new Error('Controlla quantità e costo delle righe.');const item=await c.query('SELECT id,description FROM inventory_items WHERE id=$1',[ids[i]]);if(!item.rowCount)throw new Error('Un ricambio selezionato non è valido.');await c.query(`INSERT INTO purchase_order_lines(purchase_order_id,item_id,description,quantity_ordered,unit_cost) VALUES($1,$2,$3,$4,$5)`,[p.rows[0].id,ids[i],item.rows[0].description,qty,cost]);}await c.query('INSERT INTO audit_log(user_id,action,entity_type,entity_id) VALUES($1,$2,$3,$4)',[req.session.user.id,'create','purchase_order',String(p.rows[0].id)]);await c.query('COMMIT');flash(req,`Ordine ACQ-${p.rows[0].id} registrato.`);res.redirect(`/purchases/${p.rows[0].id}`);}catch(e){await c.query('ROLLBACK');flash(req,e.message);res.redirect('/purchases/new');}finally{c.release();}});
app.get('/purchases/:id',needAuth,allow('owner','admin','manager','warehouse'),async(req,res,next)=>{try{const p=await pool.query(`SELECT p.*,s.name AS supplier FROM purchase_orders p JOIN suppliers s ON s.id=p.supplier_id WHERE p.id=$1`,[req.params.id]);if(!p.rowCount)return res.sendStatus(404);const d=p.rows[0],lines=await pool.query(`SELECT l.*,i.sku,i.quantity AS stock FROM purchase_order_lines l LEFT JOIN inventory_items i ON i.id=l.item_id WHERE l.purchase_order_id=$1 ORDER BY l.id`,[d.id]);const rows=lines.rows.map(l=>`<tr><td>${esc(l.sku||'')}</td><td>${esc(l.description)}</td><td>${Number(l.quantity_ordered)}</td><td>${Number(l.quantity_received)}</td><td>${Number(l.stock||0)}</td><td>${Number(l.quantity_received)<Number(l.quantity_ordered)?`<form class="inline-form" method="post" action="/purchase-order-lines/${l.id}/receive">${formToken(req)}<input type="number" name="quantity" min="0.01" max="${Number(l.quantity_ordered)-Number(l.quantity_received)}" step="0.01" placeholder="Qtà arrivata" required><button class="button small">Registra arrivo</button></form>`:'Ricevuto'}</td></tr>`).join('')||'<tr><td colspan="6" class="empty">Ordine senza righe</td></tr>';res.send(page(`Ordine acquisto ACQ-${d.id}`,`${takeFlash(req)}<section class="card"><div class="detail-grid"><div><span class="muted">Fornitore</span><strong>${esc(d.supplier)}</strong></div><div><span class="muted">Data ordine</span><strong>${fmtDate(d.ordered_at)}</strong></div><div><span class="muted">Stato</span><strong>${esc(d.status)}</strong></div><div><span class="muted">Consegna prevista</span><strong>${fmtDate(d.expected_at)}</strong></div></div><p>${esc(d.notes)}</p><div class="table-wrap"><table><thead><tr><th>Codice</th><th>Ricambio</th><th>Ordinato</th><th>Ricevuto</th><th>Giacenza attuale</th><th>Registra arrivo</th></tr></thead><tbody>${rows}</tbody></table></div></section>`,req.session.user,'inventory'));}catch(e){next(e);}});
app.post('/purchase-order-lines/:id/receive',needAuth,allow('owner','admin','manager','warehouse'),async(req,res,next)=>{const c=await pool.connect();try{await c.query('BEGIN');const q=await c.query(`SELECT l.*,p.id AS purchase_order_id,p.status AS order_status FROM purchase_order_lines l JOIN purchase_orders p ON p.id=l.purchase_order_id WHERE l.id=$1 FOR UPDATE OF l,p`,[req.params.id]);if(!q.rowCount)throw new Error('Riga ordine non trovata.');const l=q.rows[0],qty=Number(req.body.quantity),remaining=Number(l.quantity_ordered)-Number(l.quantity_received);if(!Number.isFinite(qty)||qty<=0||qty>remaining)throw new Error('La quantità ricevuta deve essere maggiore di zero e non superare il residuo.');await c.query('UPDATE purchase_order_lines SET quantity_received=quantity_received+$1 WHERE id=$2',[qty,l.id]);await c.query('UPDATE inventory_items SET quantity=quantity+$1,unit_cost=$2 WHERE id=$3',[qty,l.unit_cost,l.item_id]);await c.query(`INSERT INTO stock_movements(item_id,work_order_id,movement_type,quantity,reason,user_id) VALUES($1,(SELECT work_order_id FROM purchase_orders WHERE id=$2),'purchase_receipt',$3,$4,$5)`,[l.item_id,l.purchase_order_id,qty,`Arrivo ordine ACQ-${l.purchase_order_id}`,req.session.user.id]);const state=await c.query(`SELECT count(*) FILTER (WHERE quantity_received<quantity_ordered)::int AS open,count(*)::int AS total FROM purchase_order_lines WHERE purchase_order_id=$1`,[l.purchase_order_id]);const status=Number(state.rows[0].open)===0?'received':Number(state.rows[0].open)===Number(state.rows[0].total)?'ordered':'partial';await c.query('UPDATE purchase_orders SET status=$1,received_at=CASE WHEN $1=\'received\' THEN now() ELSE received_at END WHERE id=$2',[status,l.purchase_order_id]);await c.query('INSERT INTO audit_log(user_id,action,entity_type,entity_id,details) VALUES($1,$2,$3,$4,$5)',[req.session.user.id,'receive','purchase_order',String(l.purchase_order_id),JSON.stringify({line_id:l.id,quantity:qty})]);await c.query('COMMIT');flash(req,'Arrivo registrato e giacenza aggiornata.');res.redirect(`/purchases/${l.purchase_order_id}`);}catch(e){await c.query('ROLLBACK');flash(req,e.message);res.redirect('/purchases');}finally{c.release();}});

app.get('/settings',needAuth,allow('owner','admin'),async(req,res,next)=>{try{const s=(await pool.query('SELECT * FROM workshop_settings WHERE id=1')).rows[0];res.send(page('Impostazioni officina',`${takeFlash(req)}<section class="card"><h2>Dati e aspetto officina</h2><form method="post" action="/settings">${formToken(req)}<div class="logo-preview"><img src="${s.logo_data?'/workshop-logo':esc(s.logo_path)}" alt="Logo officina"><span>Logo intestazione documenti</span></div><div class="form-grid">${input('Ragione sociale / nome officina','business_name','text',s.business_name,true)}${input('Indirizzo','address','text',s.address)}${input('Telefono','phone','tel',s.phone)}${input('Email','email','email',s.email)}${input('Partita IVA','vat_number','text',s.vat_number)}${input('Codice fiscale','tax_code','text',s.tax_code)}${input('Tariffa oraria predefinita (€)','hourly_rate','number',s.hourly_rate)}${input('Prefisso documenti','document_prefix','text',s.document_prefix)}</div><button class="button primary">Salva impostazioni</button></form><form class="inline-form logo-upload" method="post" action="/settings/logo" enctype="multipart/form-data">${formToken(req)}<label>Carica logo PNG o JPEG (massimo 3 MB)<input name="logo" type="file" accept="image/png,image/jpeg" required></label><button class="button">Salva logo</button></form>${s.logo_data?`<form method="post" action="/settings/logo/reset">${formToken(req)}<button class="button">Ripristina logo GO</button></form>`:''}</section><section class="card"><h2>Testi e condizioni</h2><p class="muted">Questi campi sono modelli modificabili dell’officina. Devono essere verificati da professionisti incaricati prima dell’uso: il gestionale non certifica conformità legale o privacy.</p><form method="post" action="/settings">${formToken(req)}<input type="hidden" name="business_name" value="${esc(s.business_name)}"><input type="hidden" name="address" value="${esc(s.address)}"><input type="hidden" name="phone" value="${esc(s.phone)}"><input type="hidden" name="email" value="${esc(s.email)}"><input type="hidden" name="vat_number" value="${esc(s.vat_number)}"><input type="hidden" name="tax_code" value="${esc(s.tax_code)}"><input type="hidden" name="hourly_rate" value="${esc(s.hourly_rate)}"><input type="hidden" name="document_prefix" value="${esc(s.document_prefix)}"><label>Condizioni del servizio di riparazione<textarea name="repair_terms">${esc(s.repair_terms)}</textarea></label><label>Informativa privacy clienti<textarea name="privacy_notice">${esc(s.privacy_notice)}</textarea></label><button class="button primary">Salva testi</button></form></section>`,req.session.user,'settings'));}catch(e){next(e);}});
app.post('/settings',needAuth,allow('owner','admin'),async(req,res,next)=>{try{await pool.query(`UPDATE workshop_settings SET business_name=$1,address=$2,phone=$3,email=$4,vat_number=$5,tax_code=$6,hourly_rate=$7,document_prefix=$8,repair_terms=COALESCE($9,repair_terms),privacy_notice=COALESCE($10,privacy_notice),updated_at=now() WHERE id=1`,[req.body.business_name,req.body.address||'',req.body.phone||'',req.body.email||'',req.body.vat_number||'',req.body.tax_code||'',req.body.hourly_rate||55,req.body.document_prefix||'GO',req.body.repair_terms===undefined?null:req.body.repair_terms,req.body.privacy_notice===undefined?null:req.body.privacy_notice]);await pool.query(`INSERT INTO audit_log(user_id,action,entity_type,entity_id,details) VALUES($1,'update','workshop_settings','1',$2)`,[req.session.user.id,JSON.stringify({fields:['business_name','address','phone','email','vat_number','tax_code','hourly_rate','document_prefix','repair_terms','privacy_notice']})]);flash(req,'Impostazioni salvate.');res.redirect('/settings');}catch(e){next(e);}});
app.post('/settings/logo',needAuth,allow('owner','admin'),async(req,res,next)=>{try{const file=req.file;if(!file)throw new Error('Seleziona un logo PNG o JPEG.');const png=file.mimetype==='image/png'&&file.buffer.subarray(0,8).equals(Buffer.from([137,80,78,71,13,10,26,10]));const jpeg=file.mimetype==='image/jpeg'&&file.buffer[0]===0xff&&file.buffer[1]===0xd8&&file.buffer[2]===0xff;if(!png&&!jpeg)throw new Error('Il file non è un’immagine PNG o JPEG valida.');await pool.query(`UPDATE workshop_settings SET logo_data=$1,logo_mime=$2,logo_path='/workshop-logo',updated_at=now() WHERE id=1`,[file.buffer,file.mimetype]);await pool.query(`INSERT INTO audit_log(user_id,action,entity_type,entity_id,details) VALUES($1,'logo_upload','workshop_settings','1',$2)`,[req.session.user.id,JSON.stringify({mime:file.mimetype,bytes:file.size})]);flash(req,'Logo salvato nel database e disponibile nei documenti.');res.redirect('/settings');}catch(e){flash(req,e.message);res.redirect('/settings');}});
app.post('/settings/logo/reset',needAuth,allow('owner','admin'),async(req,res,next)=>{try{await pool.query(`UPDATE workshop_settings SET logo_data=NULL,logo_mime='image/png',logo_path='/assets/brand/go-logo.png',updated_at=now() WHERE id=1`);flash(req,'Ripristinato il logo GO predefinito.');res.redirect('/settings');}catch(e){next(e);}});

app.get('/work-orders/:id/pdf',needAuth,async(req,res,next)=>{
  try{
    const r=await pool.query(`SELECT w.*,v.plate,v.make,v.model,v.vin,c.name AS customer,c.phone,c.email,s.business_name,s.address,s.phone AS workshop_phone,s.email AS workshop_email,s.vat_number,s.logo_path,s.logo_data FROM work_orders w JOIN vehicles v ON v.id=w.vehicle_id JOIN customers c ON c.id=w.customer_id CROSS JOIN workshop_settings s WHERE w.id=$1`,[req.params.id]);
    if(!r.rowCount)return res.sendStatus(404);
    const d=r.rows[0];
    res.setHeader('Content-Type','application/pdf');
    res.setHeader('Content-Disposition',`inline; filename="GO-Ordine-${d.id}.pdf"`);
    const pdf=new PDFDocument({size:'A4',margin:48});
    pdf.pipe(res);
    drawWorkshopLogo(pdf,d.logo_data);
    pdf.fillColor('#202a39').fontSize(17).font('Helvetica-Bold').text(d.business_name,205,48,{width:342});
    pdf.fillColor('#667085').fontSize(8).font('Helvetica').text([d.address,d.workshop_phone,d.workshop_email,d.vat_number?`P. IVA ${d.vat_number}`:''].filter(Boolean).join(' · '),205,74,{width:342});
    pdf.y=115;pdf.strokeColor('#ef6b22').lineWidth(2).moveTo(48,pdf.y).lineTo(547,pdf.y).stroke();
    pdf.moveDown(1).fillColor('#202a39').fontSize(17).font('Helvetica-Bold').text(`SCHEDA DI PRESA IN CARICO · GO-${d.id}`);
    pdf.moveDown(.8).fontSize(10).font('Helvetica');
    const rows=[['Cliente',d.customer],['Contatto',[d.phone,d.email].filter(Boolean).join(' · ')||'—'],['Veicolo',`${d.plate} · ${d.make} ${d.model}`],['VIN',d.vin||'—'],['Data ingresso',fmtDate(d.created_at)],['Chilometraggio',`${Number(d.mileage_in).toLocaleString('it-IT')} km`],['Livello carburante / carica',d.fuel_level||'—'],['Problema segnalato',d.complaint||'—'],['Note',d.notes||'—']];
    for(const [label,value] of rows){pdf.font('Helvetica-Bold').text(`${label}: `,{continued:true});pdf.font('Helvetica').text(String(value));pdf.moveDown(.45);}
    pdf.moveDown(1).text('Condizioni del veicolo e autorizzazione alla diagnosi/lavorazioni approvate:');
    pdf.moveDown(3).text('Firma cliente: ______________________________     Data: ____ / ____ / ______');
    pdf.moveDown(3).fillColor('#667085').fontSize(8).text('Documento gestionale di presa in carico. Gli interventi devono essere eseguiti secondo il preventivo approvato e le condizioni sottoscritte.');
    pdf.end();
  }catch(e){next(e);}
});

app.use((err,req,res,_next)=>{console.error(err);if(res.headersSent)return;const uploadError=String(err.code||'').startsWith('LIMIT_');const status=err.code==='23503'||err.code==='22P02'||uploadError?400:500;const message=err.code==='LIMIT_FILE_SIZE'?'Un file supera il limite di dimensione.':err.code==='LIMIT_FILE_COUNT'?'Hai selezionato troppi file.':uploadError?'Il file selezionato non è valido.':err.message;res.status(status).send(page(status===500?'Errore':'Dati non validi',`<section class="card"><h2>${status===500?'Si è verificato un errore':'Controlla i dati inseriti'}</h2><p>${status===500?'Riprova. Se il problema continua, contatta l’amministratore.':esc(message)}</p><a class="button" href="javascript:history.back()">Torna indietro</a></section>`,req.session?.user));});

const port=Number(process.env.PORT||10000);
app.listen(port,'0.0.0.0',()=>console.log(`GO Gestione Officina in ascolto sulla porta ${port}`));
